using namespace std;

int dfs(vector<vector<int>> dp, const vector<int> &v, const int &n, int i, int s) {
	if (s <= 0) return 0;
	if (dp[i][s] != -1) return dp[i][s];
	if (v[i] > s) return dp[i][s] = 0;
	if (v[i] == s) return dp[i][s] = i+1;
	int t = s - v[i];
	int c = 0;
	for (int p = 0; p < i; p++) {
		c += dfs(dp, v, n, p, t);
	}
	return dp[i][s] = c;
}

