const LL MOD = 998244353;
LL dp[3001][3001][3];

void solve(long long N, long long S, std::vector<long long> A){
    dp[0][0][0] = 1;

    REP(i, N) {
        REP(j, S+1) {
            dp[i+1][j][0] += dp[i][j][0];
            dp[i+1][j][0] %= MOD;
            if(j+A[i] <= S) {
                dp[i+1][j+A[i]][1] += ((dp[i][j][0] * (i+1)) % MOD);
                dp[i+1][j+A[i]][1] %= MOD;
                dp[i+1][j+A[i]][2] += ((dp[i][j][0] * ((i+1) * (N-i) % MOD)) % MOD);
                dp[i+1][j+A[i]][2] %= MOD;
            }

            dp[i+1][j][1] += dp[i][j][1];
            dp[i+1][j][1] %= MOD;
            if(j+A[i] <= S) {
                dp[i+1][j+A[i]][1] += dp[i][j][1];
                dp[i+1][j+A[i]][1] %= MOD;
                dp[i+1][j+A[i]][2] += ((dp[i][j][1] * (N-i)) % MOD);
                dp[i+1][j+A[i]][2] %= MOD;
            }

            dp[i+1][j][2] += dp[i][j][2];
            dp[i+1][j][2] %= MOD;
        }
    }

    cout << dp[N][S][2] << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long S;
    scanf("%lld",&S);
    std::vector<long long> A(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&A[i]);
    }
    solve(N, S, std::move(A));
    return 0;
}

