int dp(int n,int m)
{
  if(memo[n][m]!=-1)
  {
    return memo[n][m];
  }

  int u,v;

  u=dp(n-1,m);
  u%=MOD;
  if(m>A[n])
  {
    u+=dp(n-1,m-A[n]);
  }
  else if(m==A[n])
  {
    u+=dp(n-1,0)+1;
  }
  u%=MOD;
  memo[n][m]=u;
  return u;

}

