	REP(i, N) {
		REP(j, S) {
			if (j == 0 && A[i] <= S) {
				dp[i + 1][A[i]] += i + 1;
			}
			if (dp[i][j] == 0) continue;
			dp[i + 1][j] += dp[i][j];
			if (j + A[i] > S) continue;
			dp[i + 1][j + A[i]] += dp[i][j];
		}
	}

	mint ans = 0;
	FOR(i, 1, N + 1) ans += dp[i][S] * (N - i + 1);
	cout << ans << endl;
	return 0;
}

