const long long MOD = 998244353;
struct mint {
 int x;
 mint(int x=0):x((x%MOD+MOD)%MOD){}
 mint& operator+=(const mint a) {
   if ((x += a.x) >= MOD) x -= MOD;
   return *this;
 }
 mint& operator-=(const mint a) {
   if ((x += MOD-a.x) >= MOD) x -= MOD;
   return *this;
 }
 mint& operator*=(const mint a) {
   (x *= a.x) %= MOD;
   return *this;
 }
 mint operator+(const mint a) const {
   mint res(*this);
   return res+=a;
 }
 mint operator-(const mint a) const {
   mint res(*this);
   return res-=a;
 }
 mint operator*(const mint a) const {
   mint res(*this);
   return res*=a;
 }
 mint pow(int t) const {
   if (!t) return 1;
   mint a = pow(t>>1);
   a *= a;
   if (t&1) a *= *this;
   return a;
 }
