		dp[i + 1][0] += dp[i][0];

		dp[i + 1][A[i]] %= MOD;
		dp[i + 1][0] %= MOD;
		for (int j = 1;j < S;j++) {
			dp[i][j] %= MOD;
			dp[i + 1][j + A[i]] += dp[i][j];
			dp[i + 1][j] += dp[i][j];
			dp[i + 1][j + A[i]] %= MOD;
			dp[i + 1][j] %= MOD;
		}
		ans += dp[i][S] * (N - i + 1) % MOD;
		ans %= MOD;
	}
	cout << ans << endl;
}

