int dp[MAXN][MAXN][2];
const int MOD = 998244353;

int rec(int idx,int sum,int flag){
    if(idx == n+1) return 0;

    int &ans = dp[idx][sum][flag];

    if(ans != -1) return ans;

    ans = 0;

    ans = (ans + rec(idx+1,sum,flag));

    if(flag == 0){
        int n_S = sum + a[idx];
        if(n_S < S) ans = (ans + (idx*rec(idx+1,n_S,1))%MOD)%MOD;
        if(n_S == S) ans = (ans + (idx*(n-idx+1))%MOD)%MOD; 
    }else {
        int n_S = sum + a[idx];
        if(n_S < S) ans = (ans + rec(idx+1,n_S,flag)%MOD)%MOD;
        if(n_S == S) ans = (ans + (n-idx+1)%MOD)%MOD; 
    }

    return ans;
}

