    // i番目まで考えたとき和がsになる場合の数を全て計算:O(NS)
    for (int i = 0; i < N; ++i)
    {
        for (int s = 0; s <= S; ++s)
        {    
            // --- Aiを和に加えない場合 --------
            // t = 0 : L, Rともに未定
            (dp[i + 1][s][0] += dp[i][s][0]) %= MOD;
