            (dp[i + 1][s][1] += dp[i][s][0] + dp[i][s][1]) %= MOD;
            // t = 2 : L, Rともに確定
            (dp[i + 1][s][2] += dp[i][s][0] + dp[i][s][1] + dp[i][s][2]) %= MOD;
            // --- Aiを和に加える場合 --------
            // 和がS以下になる場合の数を全て記録していく
            int tmpSum = s + As[i];
            if (tmpSum <= S)
            {
                (dp[i + 1][tmpSum][1] += dp[i][s][0] + dp[i][s][1]) %= MOD;
                (dp[i + 1][tmpSum][2] += dp[i][s][0] + dp[i][s][1]) %= MOD;
            }
        }
    }
