ll dp[3005][3005];

ll go(ll i, ll s, v64 &arr)
{
	if (i >= sz(arr) && s != 0)
		return 0;
	if (s == 0)
		return (sz(arr) - i + 1);
	if (dp[i][s] != -1)
		return dp[i][s];
	return (dp[i][s] = add(go(i + 1, s - arr[i], arr), go(i + 1, s, arr), MOD));
}

void solve()
{
	ll n, s;
	cin >> n >> s;
	v64 arr(n, 0);
	for (int i = 0; i < n; i++)
		cin >> arr[i];
	memset(dp, -1, sizeof(dp));
	go(0, s, arr);
	dp[n][s] = 0;
	ll ans = 0;
	for (ll i = 0; i < n; i++)
	{
		ll temp = mul(i + 1ll, add(dp[i][s], MOD - dp[i + 1][s], MOD), MOD);
		ans = add(ans, temp, MOD);
	}
	cout << ans << ln;
	return;
}

