const int mod = 998244353;

void add_self (int & a, int b) {
	a += b;
	if (a >= mod) a -= mod;
}

int mul (int a, int b) {
	return (ll) a * b % mod;
}

int main() {
	ios_base::sync_with_stdio (false);
	cin.tie (0); cout.tie (0);
	int n, s;
	cin >> n >> s;
	vector < int > a (n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	int answer = 0;
	vector < int > dp (s + 1);
	for (int i = 0; i < n; i++) {
		if (a[i] <= s) {
			add_self (answer, mul (n - i, dp[s - a[i]]));
		}
		for (int j = s - a[i]; j >= 1; j--) {
			dp[j + a[i]] += dp[j];
		}

		if (a[i] <= s) {
			add_self (dp[a[i]], i + 1);
		}
		if (a[i] == s) {
			add_self (answer, mul (i + 1, n - i));
		}
	}
	cout << answer << endl;
	return 0;
}

