const ll MOD = 998244353;

int N;
ll  P = 0;

void rec(const vector<vector<long long>> &dp, const vector<int> &a, int i, int j, deque<int> &keiro) {
	if (i == 0) {
		if (j == 0) {
			ll f = keiro.front()+1LL;
			ll b = N-keiro.back();
			ll k = (f*b)%MOD;
			P += k;
			P %= MOD;
		}
		return;
	}

	// 上へ遡る (dp[i-1][j] == 0) だったら無視)
	if (dp[i-1][j]) {
		rec(dp, a, i-1, j, keiro);
	}
	// 左上へ遡る (dp[i-1][j-a[i-1]] == 0 だったら無視)
	if (j-a[i-1] >= 0 && dp[i-1][j-a[i-1]]) {
		keiro.push_front(i-1);
		rec(dp, a, i-1, j-a[i-1], keiro);
		keiro.pop_front();
	}
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout<<fixed<<setprecision(10);

	N=in();
	int S=in();
	auto A=vecin(N);
	vector<vector<ll>> dp(N+1,vector<ll>(S+1,0));
	dp[0][0] = 1;

	vector<int> H;
	REP(i,N){
		REP(j,S+1){
			dp[i+1][j] += dp[i][j];
			dp[i+1][j] %= MOD;
			if(j>=A[i]){
				if(dp[i][j-A[i]]>0) H.push_back(i);
				dp[i+1][j] += dp[i][j-A[i]];
				dp[i+1][j] %= MOD;
			}
		}
	}

	deque<int> keiro;
	rec(dp, A, N, S, keiro);

	out(P);
	return 0;
}

