				if(dp[i+1][j]>=INF) dp[i+1][j]=dp[i][j];
				else{
					dp[i+1][j]+=dp[i][j];
				}
			}

			if(j+A[i]<=S){
				if(dp[i+1][j+A[i]]>=INF){
					if(j==0){
						dp[i+1][j+A[i]]=i+1;
					}
					else{
						dp[i+1][j+A[i]]=dp[i][j];
					}
				}
				else{
					if(j==0){
						dp[i+1][j+A[i]]+=i+1;
					}
					else{
						dp[i+1][j+A[i]]+=dp[i][j];
					}
