template<typename T, typename U, typename V> int mpow(const T a, const U b, const V m) {
    assert(b >= 0);
    int x = a, res = 1;
    U p = b;
    while (p > 0) {
        if (p & 1) (res *= x) %= m;
        (x *= x) %= m;
        p >>= 1;
    }
    return res;
}
