int solve(int pos, int k) {
	if (k == 0) return N - pos + 1;
	if (pos == N) return 0;

	int& ret = cache[pos][k];
	if (ret != -1) return ret;

	ret = solve(pos + 1, k);
	if (k - v[pos] >= 0) ret += solve(pos + 1, k - v[pos]);
	return ret;
}

