int F(int i, int s)
{
    // indices >= i, sum exactly s.
    const int N = A.size();
    if (s == 0)
        return 1;
    if (i == N)
        return 0;

    int& ans = dp[i][s];
    if (ans >= 0)
        return ans;
    ans = F(i + 1, s);
    if (A[i] == s) {
        ans += (N - i);
        ans %= MOD;
    } else if (s > A[i]){
        ans += F(i + 1, s - A[i]);
        ans %= MOD;
    }

    return ans;
};

