        if (A[i] == S) {
            ret += (i + 1) * 1LL * (N - i) % MOD;
            ret %= MOD;
            continue;
        }

        ret += (i + 1) * 1LL * F(i + 1, S - A[i]) % MOD;
        ret %= MOD;
