    if(s == 0)
        return (n-idx+1);
    if(idx >= n or s < 0)
        return 0;
    int &ans = dp[idx][s];
    if(ans != -1)
        return ans;
    ans = 0;
    if(s == S){
        ans += solve(idx+1, s);
        // if(idx==0) cout<<ans<<" ";
        ans %= MOD;
        ans += (idx+1)*solve(idx+1, s-a[idx]);
        ans %= MOD;
        // if(idx==0)cout<<ans<<endl;
    }
    else{
        ans += solve(idx+1, s);
        ans %= MOD;
        ans += solve(idx+1, s-a[idx]);
        ans %= MOD;
    }
    ans %= MOD;
    ans += MOD;
    ans %= MOD;
    return ans;
}

