const int N = 3e3 + 10, mod = 998244353;

int n, sum;
int dp[N][N];
int arr[N];

int solve(int i, int s) {
    if(s > sum) return 0;
    if(sum == s) return n - i + 1;
    if(i == n) return 0;
    if(dp[i][s] != -1) return dp[i][s];
    int ret = 0;
    ret = solve(i + 1, s + arr[i]);
    ret = (1ll * ret + solve(i + 1, s)) % mod;
    return dp[i][s] = ret;
}

