        memset(dp, -1, sizeof(dp));
        for(int i = 0; i < n; i++) {
            ans = (ans + 1ll * (i + 1) * solve(i + 1, arr[i]) % mod) % mod;
        }
        printf("%d\n", ans);
    }    
    return 0;
}

