const int MM = 3005;
ll mod = 998244353, ans;
int n, a[MM], s, dpl[MM], dpr[MM], psl[MM], psr[MM];

void go(int l, int r){
    if(l == r){
        if(a[l] == s)
            ans++;
        ans %= mod;
        return;
    }
    int m = (l+r)/2;
//    print(l, m, r);
    for(int j = 0; j < MM; j++)
        dpl[j] = psl[j] = dpr[j] = psr[j] = 0;
    dpl[0] = dpr[0] = 1;
    for(int i = m; i >= l; i--){
        for(int j = 3000; j >= 0; j--){
            if(j >= a[i]){
                dpl[j] += dpl[j-a[i]];
                dpl[j] %= mod;
            }
            psl[j] += dpl[j];
            psl[j] %= mod;
        }
    }
    for(int i = m+1; i <= r; i++){
        for(int j = 3000; j >= 0; j--){
            if(j >= a[i]){
                dpr[j] += dpr[j-a[i]];
                dpr[j] %= mod;
            }
            psr[j] += dpr[j];
            psr[j] %= mod;
        }
    }
    for(int i = 0; i <= s; i++){
//        print(i, s-i, psl[i], psr[s-i]);
        ans += psl[i]*psr[s-i];
        ans %= mod;
    }
    go(l, m);
    go(m+1, r);
}

