                    if (a[i - 1] < j) dp[i][j][k] = dp[i - 1][j - a[i - 1]][0];
                    if (a[i - 1] == j) dp[i][j][k] = i;
                }
            }
        }
    }
    ll ans = 0;
    for (int i = 1; i <= n; i++) {
        ans += (ll)dp[i][s][1] * (ll)(n - i + 1);
        ans %= mod;
    }
