    for(int i = 0; i < n; i++) {
        vector<ll> new_dp = dp;
        for(int j = 1; j <= s; j++) {
            if (dp[j] > 0 && j+arr[i] <= s) {
                new_dp[j+arr[i]] += dp[j];
                new_dp[j+arr[i]] %= mod;
            }
        }
        if (arr[i] <= s) { // multiply first element to extend LHS
            new_dp[arr[i]] += i+1;
        }
        dp = new_dp;
        ans += dp[s]; // extend right each time
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

