template<class T> string deb_tos(const vector<T> &a, ll W = inf) {    stringstream ss;    if (W == inf)W = min(sz(a), DEB_LEN);    if (sz(a) == 0)return ss.str();    rep(i, W) {        ss << deb_tos(a[i]);        if (typeid(a[i]) == typeid(P)) { ss << endl; } else { ss << " "; }    }    return ss.str();}
/*@formatter:on*/
template<class T> string deb_tos(const vector<vector<T> > &a, vi H, vi W, int key = -1) {
    stringstream ss;
    ss << endl;
    vi lens(sz(W));
    fora(h, H) {
        rep(wi, sz(W)) {
            if (sz(a[h]) <= W[wi])break;
            lens[wi] = max(lens[wi], sz(deb_tos(a[h][W[wi]])) + 1);
            lens[wi] = max(lens[wi], sz(deb_tos(W[wi])) + 1);
        }
    }
    if (key == -1)ss << " *|"; else ss << " " << key << "|";
    int wi = 0;
    fora(w, W) {
        ss << std::right << std::setw(lens[wi]) << w;
        wi++;
    }
    ss << "" << endl;
    rep(i, sz(W))rep(lens[i])ss << "_";
    rep(i, 3)ss << "_";
    ss << "" << endl;
    fora(h, H) {
        ss << std::right << std::setw(2) << h << "|";
        int wi = 0;
        fora(w, W) {
            if (sz(a[h]) <= w)break;
            ss << std::right << std::setw(lens[wi]) << deb_tos(a[h][w]);
            wi++;
        }
        ss << "" << endl;
    }
    return ss.str();
}
template<class T> string deb_tos(const vector<vector<T> > &a, ll H = inf, ll W = inf, int key = -1) {
    H = (H != inf) ? H : min({H, sz(a), DEB_LEN_H});
    W = min({W, sz(a[0]), DEB_LEN_H});
    vi hs, ws;
    rep(h, H) { hs.push_back(h); }
    rep(w, W) { ws.push_back(w); }
    return deb_tos(a, hs, ws, key);
}
