template<class F> auto mgrd(dou ok, dou ng, F f, int kai = 100) {if (ok < ng)        rep(i, kai) {            dou mid = (ok + ng) / 2;            if (f(mid))ok = mid; else ng = mid;        }    else        rep(i, kai) {            dou mid = (ok + ng) / 2;            if (f(mid))ok = mid; else ng = mid;        }    return ok;}
