    { 
    		ans+=(1LL*(p.y+1)*(n-p.x))%MV;
    		debug(p.y,p.x,ans);
        return; 
    } 

    if (dp[i-1][sum]) 
    { 

        ii b = p; 
        get(arr, i-1, sum, b); 
    } 

    if (sum >= arr[i] && dp[i-1][sum-arr[i]]) 
    { 
        if(p.x==-1) {p.x=i;p.y=i;} else p.y=i;
        get(arr, i-1, sum-arr[i], p); 
    } 
} 

void solve(vi& arr, int n, int sum) 
{   dp.resize(n,vector<bool> (sum+1,false));
    for (int i=0; i<n; ++i) 
    { 
        dp[i][0] = true; 
    } 

    if (arr[0] <= sum) 
       dp[0][arr[0]] = true; 

    for (int i = 1; i < n; ++i) 
        for (int j = 0; j < sum + 1; ++j) 
            dp[i][j] = (arr[i] <= j) ? dp[i-1][j] || 
                                       dp[i-1][j-arr[i]] 
                                     : dp[i - 1][j]; 
    if (dp[n-1][sum] == false) 
    { 
        return;
    } 

    ii p{-1,-1};
    get(arr, n-1, sum, p);
} 

