ll DP(int ty, int i, int sum) {
  if(i < 1) return sum == 0;
  if(dp[ty][i][sum] != -1) return dp[ty][i][sum];

  if(ty == 2) {
    dp[2][i][sum] = DP(2, i - 1, sum) + DP(1, i, sum);
    if(dp[2][i][sum] >= MOD) dp[2][i][sum] -= MOD;
