    if(dp[1][i][sum] >= MOD) dp[1][i][sum] -= MOD;
    dp[1][i][sum] += DP(0, i, sum);
    if(dp[1][i][sum] >= MOD) dp[1][i][sum] -= MOD;
  } else {
    dp[0][i][sum] = DP(0, i - 1, sum);
  }
  return dp[ty][i][sum];
}

