    cin >> N >> S;

    vector<LL> A(N);
    cin >> A;


    vector<vector<ModInt<mod>>> dp(N + 1, vector<ModInt<mod>>(S + 1, 0));
    dp[0][0] = 1;

    ModInt<mod> ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= S; j++) {
            dp[i + 1][j] += dp[i][j];
            int to = j + A[i];
            if (to <= S) {
                dp[i + 1][to] += dp[i][j];
            }
        }
        ModInt<mod> diff = dp[i + 1][S] - dp[i][S];
        ans += diff * (i) * max(0LL, N - i - 1);
    }

    cout << ans << endl;

}

