int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N, S;
	cin >> N >> S;

	vector<int> A(N);
	for (int i = 0; i < N; i++) cin >> A[i];

	vector<mint> dp(S + 1); //多項式の係数

	mint ans = 0;
	// 遷移は F_{i+1} = (1 + F_i)* x^{A_i}
	// x^Sの係数を足し合わせる
	for (int i = 0; i < N; i++) {
		dp[0] += 1;
		for (int j = S; j >= 0; j--) {
			if (j + A[i] <= S) dp[j + A[i]] += dp[j];
		}
		ans += dp[S];
	}

	cout << ans << "\n";

	return 0;
}

