    return true; 

    // If first and last 
    // characters do not match 
    if (str[s] != str[e]) 
    return false; 

    // If there are more than  
    // two characters, check if  
    // middle substring is also  
    // palindrome or not. 
    if (s < e + 1) 
    return isPalRec(str, s + 1, e - 1); 

    return true; 
} 

bool isPalindrome(string& str) 
{ 
int n = str.length(); 
 if(n==0)return true;

return isPalRec(str, 0, n - 1); 
} 
