const LL MOD = 998244353;

void solve(long long N, long long S, std::vector<long long> A){
    LL ans = 0;
    REP(i, N) {
        map<int, int> memo;
        memo[0] = 1;
        REP2(j, i, N) {
            map<int, int> tmp;
            for (const auto& [key, value] : memo){
                if(key + A[j] <= S) {
                    if(tmp.count(key+A[j]) == 1) {
                        tmp[key+A[j]] += value;
                        tmp[key+A[j]] %= MOD;
                    } else {
                        tmp[key+A[j]] = value;
                    }
                }

                if(tmp.count(key) == 1) {
                    tmp[key] += value;
                    tmp[key] %= MOD;
                } else {
                    tmp[key] = value;
                }
            }

            memo = tmp;
            ans += memo[S];
            ans %= MOD;
        }
    }

    cout << ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long S;
    scanf("%lld",&S);
    std::vector<long long> A(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&A[i]);
    }
    solve(N, S, std::move(A));
    return 0;
}

