long search(vector<int> &a,int l,int r,int temp,vector<vector<long>> &pdata,int c)
{
    if(temp == 0)
    {
        pdata[c][l-1] ++;
        if(l-1 != N)
        {
            for(int i = 0;i<c;i++)
            {
                pdata[i][l-1]++;
            }
        }
        return 1;
    }
    if(l > r || (l == r && temp != a[l]))
    {
        return 0;
    }
    long ans = 0;

    //ここが二度手間
    if(temp == S)
    {
        ans += search(a,l+1,r,temp,pdata,c+1);
    }
    else
    {
        ans += search(a,l+1,r,temp,pdata,c);
    }

    //pdata.push_back(ans);
    if(temp >= a[l])
    {
        ans += search(a,l+1,r,temp-a[l],pdata,c);
    }

    if(temp == S)
    {
    pdata[c][r] = mod(ans);
    }
    return mod(ans);
}

