void solve() {
  ll N, S;
  cin >> N >> S;

  VL as(N);
  rep(i, N) cin >> as[i];

  // dp[i][j][k]: i 番目の要素までで和が j となる通り。 k: 0, 1, 2 順に
  // 左端未定, 左端確定, 右端確定
  V<V<V<mint>>> dp(N + 1, V<V<mint>>(S + 1, V<mint>(3)));

  dp[0][0][0] = 1;

  rep(i, N) rep(j, S + 1) {
    dp[i + 1][j][0] += dp[i][j][0];
    dp[i + 1][j][1] += dp[i][j][0] + dp[i][j][1];
    dp[i + 1][j][2] += dp[i][j][0] + dp[i][j][1] + dp[i][j][2];

    if (j + as[i] <= S) {
      dp[i + 1][j + as[i]][1] += dp[i][j][0] + dp[i][j][1];
      dp[i + 1][j + as[i]][2] += dp[i][j][0] + dp[i][j][1];
    }
  }

  mint res = dp[N][S][2];
  cout << res << endl;
}

