				//printf("dp[%lld][%lld] += dp[%lld][%lld]\n", i, j+A[i],i-1,j);
				dp[i][j + A[i]] += dp[i-1][j];
			}
			dp[i][j] %= MOD;
		}
	}
	int ans = 0;

	rep(i, N+1) {
		ans += dp[i][S];
		ans %= MOD;
	}

