ll ans = 0;

ll dp[3005][3005];
ll sum[3005];

inline void inc(ll& a, ll x) {
  a += x;
  if (a >= mod) a -= mod;
}

void rec(int l, int r) {
  if (l == r) {
    if (a[l] == k) inc(ans, 1);
    return;
  }

  int m = (l + r) / 2;
  f1r(i, l, r + 1) f1r(j, 1, k + 1) dp[i][j] = 0;

  // left
  inc(dp[m][a[m]], 1);
  f1rd(i, m - 1, l) {
    inc(dp[i][a[i]], 1);
    f1r(j, 1, k + 1 - a[i]) inc(dp[i][j + a[i]], dp[i + 1][j]);
    f1r(j, 1, k + 1) inc(dp[i][j], dp[i + 1][j]);
  }
  f0r(i, k + 1) {
    sum[i] = 0;
    f1r(j, l, m + 1) inc(sum[i], dp[j][i]);
  }

  // right
  inc(dp[m + 1][a[m + 1]], 1);
  f1r(i, m + 2, r + 1) {
    inc(dp[i][a[i]], 1);
    f1r(j, 1, k + 1 - a[i]) inc(dp[i][j + a[i]], dp[i - 1][j]);
    f1r(j, 1, k + 1) inc(dp[i][j], dp[i - 1][j]);
  }

  ll lspan = m - l + 1;
  // combine
  f1r(i, m + 1, r + 1) {
    f1r(j, 1, k) {
      ll v = dp[i][j];
      v = (v * sum[k - j]) % mod;
      inc(ans, v);
    }
    inc(ans, (dp[i][k] * lspan) % mod);
    inc(ans, sum[k]);
  }

  // ao(sum, k + 1);

  rec(l, m); rec(m + 1, r);
}

void solve() {
  cin >> n >> k;
  ai(a, n);

  rec(0, n - 1);

  cout << ans << '\n';
}

