LL rev(const VVLL &dp, VVLL &memo, const VI &a, int pos, int cnt) {
    int n = dp.size();
    if (pos < 0 || dp[pos][cnt] == 0) return 0;
    //if (pos < 0) return 0;
    if (memo[pos][cnt] > -1) return memo[pos][cnt];
    //cerr << pos << ", " << cnt << endl;
    LL ret = 0;
    if (cnt == a[pos]) {
        //dump(pos);
        ret += (1LL * (pos + 1)) % MOD;
    }
    //return (rev(dp,memo,a,pos-1,cnt) + (rev(dp,memo,a,pos-1,cnt-a[n-1]) * (n - pos)) % MOD) % MOD;
    ret = (ret + (rev(dp,memo,a,pos-1,cnt) + (rev(dp,memo,a,pos-1,cnt-a[pos]) * (n - pos)) % MOD) % MOD) % MOD;
    return memo[pos][cnt] = ret;
    //return ((memo[pos][cnt] = ret + (rev(dp,memo,a,pos-1,cnt)) % MOD) + (rev(dp,memo,a,pos-1,cnt-a[pos]) * (n - pos)) % MOD) % MOD;
}

