using T = map<int,ll>;

class SegmentTree {
public:
    int bit_, N;
    vector<T> buf_;

    SegmentTree(int size) {
        N = 1;
        bit_ = 0;
        while (N < size) {
            N *= 2;
            ++bit_;
        }

        buf_.resize(N*2);
    }

    void merge(T& a, T& b, T& c) {
        if (a.empty()) a[0]=1;
        if (b.empty()) b[0]=1;

        c.clear();
        for (auto& p: a){
            for (auto& q: b){
                int ix = p.first + q.first;
                if (ix <= 3000) {
                    c[ix] += MUL(p.second, q.second);
                }
            }
        }
    }

    void update(int i, T& x) {
        i = N + i - 1;

        T x2;
        merge(buf_[i], x, x2);
        if (x2 != x) return;

        buf_[i] = x;
        while (i > 0) {
			i = (i - 1) / 2;
			merge(buf_[i*2+1], buf_[i*2+2], buf_[i]);
        }
    }

    T query(int lo, int hi) {
        T res;
        query(lo, hi, 0, 0, N, res);
        return move(res);
    }
    void query(int a, int b, int k, int l, int r, T& res) {
        if (r <= a || b <= l) {
            res.clear();
            res[0] = 1;
            return;
        }

        if (a <= l && r <= b) {
            res = buf_[k];
        } else {
            T lv, rb;
            query(a, b, 2*k+1, l, (l+r)/2, lv);
			query(a, b, 2*k+2, (l+r)/2, r, rb);
			merge(lv, rb, res);
        }
    }

    void dump() {
    }
};


ll solve(int N, int S, vi& a) {
    SegmentTree st(N);

    rep(i,N){
        T ai;
        ai[0] = ai[a[i]] = 1;
        st.update(i, ai);
    }

    ll total = 0;
    rep(l,N){
        if (a[l] != S) continue;


        int left = l, right = N-left-1;

        ll cnt = 1;
        ll mag = MUL(left+1, right+1);
        total = ADD(total, MUL(cnt, mag));
    }
    repC2(l,r,N){
        int rem = S - a[l] - a[r];
        if (rem < 0) continue;
        int left = l, right = N-r-1;
        ll cnt = 0;
        if (l+1 == r) {
            cnt = (rem == 0)? 1 : 0;
        } else {
            T pat = st.query(l+1, r);
            cnt = pat[rem];
            if (cnt == 0) continue;
        }
        ll mag = MUL(left+1, right+1);
        total = ADD(total, MUL(cnt, mag));
    }
    return total;
}

