void solve(long long N, long long S, std::vector<long long> A){
    LL ans = 0;
    REP(i, N) {
        unordered_map<int, int> memo;
        memo[0] = 1;
        REP2(j, i, N) {
            unordered_map<int, int> tmp;
            for (auto kv : memo){
                if(kv.first + A[j] <= S) {
                    if(tmp.count(kv.first+A[j]) == 1) {
                        tmp[kv.first+A[j]] += kv.second;
                        tmp[kv.first+A[j]] %= MOD;
                    } else {
                        tmp[kv.first+A[j]] = kv.second;
                    }
                }

                if(tmp.count(kv.first) == 1) {
                    tmp[kv.first] += kv.second;
                    tmp[kv.first] %= MOD;
                } else {
                    tmp[kv.first] = kv.second;
                }
            }

            memo = tmp;
            ans += memo[S];
            ans %= MOD;
        }
    }

    cout << ans << endl;
}

