	vector<vector<vector<ll>>> dp(n+1,vector<vector<ll>>(s+1,vector<ll>(3,0)));
	//dp[i][j][t]:=(t=0で,Lをまだ決めていない状態),(t=1で,Lを決めたがRを決めていない状態),(t=2で,LもRも決めた状態.)
	dp[0][0][0] = 1;
