			dp[i+1][j][1] %= MOD;
			if(j + a[i] <= s){
				dp[i+1][j+a[i]][1] += dp[i][j][0];
				dp[i+1][j+a[i]][1] %= MOD;
			}
			//0->2はそれのみを取る場合.
			if(j + a[i] <= s){
				dp[i+1][j+a[i]][2] += dp[i+1][j][0];
				dp[i+1][j+a[i]][2] %= MOD;
			}

			//1->1はA[i]を取る場合と取らない場合の2通り.
			dp[i+1][j][1] += dp[i][j][1];
			dp[i+1][j][1] %= MOD;
