				dp[i+1][j+a[i]][1] += dp[i][j][1];
				dp[i+1][j+a[i]][1] %= MOD;
			}

			//1->2は取る場合と取らない場合の2通り.
			dp[i+1][j][2] += dp[i][j][1];
			dp[i+1][j][2] %= MOD;

			if(j + a[i] <= s){
				dp[i+1][j+a[i]][2] += dp[i][j][1];
				dp[i+1][j+a[i]][2] %= MOD;
			}

			//2->2もある.
			dp[i+1][j][2] += dp[i][j][2];
			dp[i+1][j][2] %= MOD;
		}
	}

	cout << dp[n][s][2] << endl;
}

