      for (int j = 0; j <= s; ++j) {
        dp[i][j] += dp[i - 1][j];
        if (j - a[i] >= 0) {
          dp[i][j] += dp[i - 1][j - a[i]];
        }
      }
    }
    Modint<> ans(0);
    for (int i = 1; i <= n; ++i) {
      ans += dp[i][s];
    }
    cout << ans << endl;
