void solve()
{
	ll N, S;  cin >> N >> S;
	vector<ll> A = cinv<ll>(N);

	vvmll dp(N, vmll(S+1,0));
	auto Dp = [&](ll i, ll w)->mll&{
		static mll dmy=0;
		if (w>S) return dmy;
		return dp[i][w];
	};

	Dp(0, 0) = 1;
	Dp(0, A[0]) = 1;

	rep(i, 0, N-2){
		ll ii = i+1;

		rep(w, 1, S-1){
			Dp(ii, w)       += Dp(i, w);
			Dp(ii, w+A[ii]) += Dp(i, w);
		}
		Dp(ii, 0)       += Dp(i, 0)+1;
		Dp(ii, 0+A[ii]) += Dp(i, 0)+1;
	}

	mll ans=0;
	rep(i, 0, N-1){
		ans += Dp(i, S) * (N-i);
	}
	cout << ans << '\n';
}


