int solve(int idx, int sum)
{
	if(sum == 0) return n - idx + 1;
	if(sum < 0) return 0;
	if(idx >= n) return 0;

	int &res = dp[idx][sum];
	if(res != -1) return res;
	res = solve(idx+1, sum) + solve(idx+1, sum - a[idx]);
	res %= 1000000007;
	return res;
}
