const int N = 3087;
const int MOD = 998244353;
int n, s, a[N];
ll dp[N][N];
int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    cin >> n >> s;
    for (int i = 1; i <= n; ++i)
        cin >> a[i];
    ll ans = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= s; ++j) {
            dp[i][j] = dp[i - 1][j];
            if (j == a[i]) {
                dp[i][j] += i;
            } else if (j > a[i]) {
                dp[i][j] += dp[i - 1][j - a[i]];
            }
            dp[i][j] %= MOD;
        }
        (ans += (dp[i][s] - dp[i - 1][s] + MOD) * (n - i + 1)) %= MOD;
    }
    cout << ans << endl;
}

