using namespace std;


struct S {
	int i;
	int j;
	int s;
};


static int64_t kRem = 998244353;

unordered_map<int64_t, int64_t> memo;

int64_t f(int i, int j, int s, vector<int>& as)
{
	int64_t idx = i * 3001LL * 3001LL + j * 3001LL + s;
	auto it = memo.find(idx);
	if (it != memo.end()) {
		return it->second;
	}

	if (i == j) {
		if (s != 0) {
			if (as[i] == s) return 1;
			else return 0;
		}
		return 1;
	}

	int64_t ans = f(i + 1, j, s, as);
	if (as[i] <= s) {
		ans += f(i + 1, j, s - as[i], as);
		ans %= kRem;
	}

	memo[idx] = ans;

	return ans;
}

int64_t dp[3001][3001][3] = {};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n, s; cin >> n >> s;
	vector<int> as(n); for (auto& a : as) cin >> a;

	int64_t ans = 0;
	FOR_LT(i, 0, n) {
		FOR_LE(j, 0, s) {
			if (i == 0) continue;

			// 1 -> 1
			dp[i][j][1] = dp[i - 1][j][1];
			if (as[i] <= j) {
				dp[i][j][1] += dp[i - 1][j - as[i]][1];
			}
			dp[i][j][1] %= kRem;

			// 2 -> 2
			dp[i][j][2] = dp[i - 1][j][2];
			// 1 -> 2
			if (as[i] <= j) {
				dp[i][j][2] += dp[i - 1][j - as[i]][1];
				dp[i][j][2] %= kRem;
				dp[i][j][2] += dp[i - 1][j][1];
			}
			dp[i][j][2] %= kRem;
		}

		// 0 -> 1, 0 -> 2
		dp[i][as[i]][1] += i + 1;
		dp[i][as[i]][1] %= kRem;
		dp[i][as[i]][2] += i + 1;
		dp[i][as[i]][2] %= kRem;

	}

	cout << dp[n - 1][s][2] << endl;

	return 0;
}

