mint dp[3005][3005];

void solve() {
    int N, S; cin >> N >> S;
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    dp[0][0] = 1;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= S; j++) {
            dp[i+1][j] += dp[i][j];
            if (j+A[i] <= S) {
                if (j == 0) dp[i+1][j+A[i]] += dp[i][j] * (i+1);
                else dp[i+1][j+A[i]] += dp[i][j];
            }
        }
    }

    mint ans = 0;
    for (int i = 0; i <= N; i++) {
        ans += dp[i][S];
    }

    cout << ans << '\n';
}

