            sumdp[i][j] = (sumdp[i - 1][j] + dp[i][j]) % Mod;
        }
    }

    ll ans = 0;
    for (int i = 1; i <= N; i++) ans = (ans + (ll)(N - i + 1)*dp[i][S])  % Mod;
    cout << ans;
    return 0;
}

