void solver::run(){
    if(!input()) return;
    auto dp = VEC(N, S+1, 2, 0_mod);
    dp[0][0][0] = 1_mod;
    if(A[0] <= S) {
        dp[0][A[0]][0] = 1_mod;
        dp[0][A[0]][1] = 1_mod;
    }
    for (int i = 1; i < N; ++i) {
        for (int s = 0; s <= S; ++s) {
            int ss = A[i] + s;
            dp[i][s][0] += dp[i-1][s][0];
            if(ss <= S){
                if(s == 0)
                    dp[i][ss][0] += i+1;
                else
                    dp[i][ss][0] += dp[i-1][s][0];
            }
            dp[i][s][1] += dp[i][s][0] + dp[i-1][s][1];
        } // end s
    } // end i
//    os << dp << endl;
    os << dp.back().back().back() << endl;
}

