  rep(i, N) irep(j, S) {
    dp[i + 1][j] = dp[i][j];
    if (j - a[i] == 0) {
      dp[i + 1][j] += Mint(i + 1);
    } else if (j - a[i] > 0) {
      dp[i + 1][j] += dp[i][j - a[i]];
    }
  }

  Mint result = (Mint)0;
  rep(i, N) { result += (dp[i + 1][S] - dp[i][S]) * Mint(N - i); }
  cout << result.value() << endl;

  return 0;
}

