    ll score = 0;
    SREP(x, L, R) {
//        score = (score+f(L, x, S)+f(x+1, R, S))%MOD;
        score = (score+f(L, x, S)*f(x+1, R, S)%MOD)%MOD;
        SREP(k, 0, S+1) {
            score = (score+f(L, x, k)*f(x+1, R, S-k)%MOD)%MOD;
