    for(int s=0; s<=S; s++){
      buf.at(s)= (s >= data.at(i)) ? dp.at(s)+ dp.at(s- data.at(i))
                                   : dp.at(s);
    }

    for(int s=0; s<=S; s++){
      dp.at(s)= buf.at(s);
    }
    ans+= buf.at(S);
  }

  cout << ans << endl; 
}

