ptvl fft (const coef& x, int wn) {
	int n = x.size();
	if (n == 1) {
		return x;
	}
	coef odd, even;
	for (int i = 0; i < (int) x.size(); i++) {
		if (i % 2 == 0) {
			even.push_back(x[i]);
		} else {
			odd.push_back(x[i]);
		}
	}
	ptvl podd = fft(odd, 1ll * wn * wn % MOD), peven = fft(even, 1ll * wn * wn % MOD);
	ptvl p(n);
	int w = 1;
	for (int i = 0; i < n/2; i++) {
		p[i] = (peven[i] + 1ll * w * podd[i]) % MOD;
		p[i + n/2] = (peven[i] - 1ll * w * podd[i] % MOD + MOD) % MOD;
		w = 1ll * w * wn % MOD;
	}
	return p;
}

int pow(int x, int y, int z) {
	if (y == 0) return 1;
	if (y % 2 == 0) {
		return pow(1ll * x * x % z, y / 2, z);
	} else {
		return 1ll * x * pow(x, y - 1, z) % z;
	}
}

int inv(int x) {
	return pow(x, MOD - 2, MOD);
}

coef ifft (const ptvl& x, int wn) {
	int n = x.size();
	ptvl res = fft(x, inv(wn));
	for (int i = 0; i < n; i++) {
		res[i] = 1ll * res[i] * inv(n) % MOD;
	}
	return res;
}

wtf dac(int l, int r) {
  coef v1(8192);
  coef v2(8192);
  coef v3(8192);
  int c = 0;
  if (l + 1 == r) {
    if (a[l] <= s) {
      v1[a[l]] = l + 1;
      v2[a[l]] = n - l;
      v3[a[l]] = 1;
      c = 1ll * v1[s] * v2[s] % MOD;
    }
    return {v1, v2, v3, c};
  }
  int m = (l + r) / 2;
  wtf wtf1 = dac(l, m);
  wtf wtf2 = dac(m, r);
  ptvl tmp1 = fft(wtf1.v1, pow(3, 119 << 10, MOD));
  ptvl tmp2 = fft(wtf2.v3, pow(3, 119 << 10, MOD));
  for (int i = 0; i < 8192; i++) {
    tmp1[i] = 1ll * tmp1[i] * tmp2[i] % MOD;
  }
  v1 = ifft(tmp1, pow(3, 119 << 10, MOD));
  for (int i = 1; i < 8192; i++) {
    if (i <= s) {
      v1[i] = (0ll + v1[i] + wtf1.v1[i] + wtf2.v1[i]) % MOD;
    } else {
      v1[i] = 0;
    }
  }
  tmp1 = fft(wtf2.v2, pow(3, 119 << 10, MOD));
  tmp2 = fft(wtf1.v3, pow(3, 119 << 10, MOD));
  for (int i = 0; i < 8192; i++) {
    tmp1[i] = 1ll * tmp1[i] * tmp2[i] % MOD;
  }
  v2 = ifft(tmp1, pow(3, 119 << 10, MOD));
  for (int i = 1; i < 8192; i++) {
    if (i <= s) {
      v2[i] = (0ll + v2[i] + wtf1.v2[i] + wtf2.v2[i]) % MOD;
    } else {
      v2[i] = 0;
    }
  }
  tmp1 = fft(wtf1.v3, pow(3, 119 << 10, MOD));
  tmp2 = fft(wtf2.v3, pow(3, 119 << 10, MOD));
  for (int i = 0; i < 8192; i++) {
    tmp1[i] = 1ll * tmp1[i] * tmp2[i] % MOD;
  }
  v3 = ifft(tmp1, pow(3, 119 << 10, MOD));
  for (int i = 1; i < 8192; i++) {
    if (i <= s) {
      v3[i] = (0ll + v3[i] + wtf1.v3[i] + wtf2.v3[i]) % MOD;
    } else {
      v3[i] = 0;
    }
  }
  for (int i = 0; i <= s; i++) {
    c += 1ll * wtf1.v1[i] * wtf2.v2[s - i] % MOD;
    c %= MOD;
  }
  return {v1, v2, v3, (int) ((0ll + wtf1.c + wtf2.c + c) % MOD)};
}

