bool multicase = false;

ll n,m,num,sum,a,b,c,d,e,h,q,p;
ll w, ans;
ll k;
ll x[500005], y[500005], z[500005];
ll dp[5005][5005];

void solve(){
    cin >> n >> k;
    for(ll i=1;i<=n;i++){
        cin >> x[i];
    }
    dp[0][0] = 1;
    ll ans = 0;
    for(ll i=1;i<=n;i++){
        for(ll j=0;j<=k;j++){
            if(j-x[i]>0){
                dp[i][j] += dp[i-1][j-x[i]];
            }else if(j-x[i]==0){
                dp[i][j] += (dp[i-1][j-x[i]] * i) % mod;
                dp[i][j] %= mod;
            }
            dp[i][j] += dp[i-1][j];
            dp[i][j] %= mod;
        }
        ll dif = dp[i][k] - dp[i-1][k];
        if(dif < 0)dif += mod;
        ans += dif * (n+1-i);
        ans %= mod;
    }

    p(ans);
    return;
}

