  ll N, S;
  io.read(N, S);
  vector<ll> A(N);
  io.read(A);
  vector<vector<ll>> dp(N + 1, vector<ll>(S + 1));
  dp[0][0] = 1;
  REP(i, N) {
    for (ll j = S; j >= 0; --j) {
      if (j >= A[i]) dp[i + 1][j] += dp[i][j - A[i]];
      dp[i + 1][j] += dp[i][j];
      dp[i + 1][j] %= MOD;
    }
    dp[i + 1][0] = dp[i][0] + 1;
  }
  ll ans = 0;
  REP(i, N) ans += dp[i + 1][S];
  ans %= MOD;
  io.writeln(ans);
  return 0;
}

