int dfs2(vector<vector<int>> &dp, vector<vector<int>> &dp2, const vector<int> &v, const int &n, int i, int t) {
	if (dp2[i][t] != -1) return dp2[i][t];
	if (i == 0) return dp2[i][t] = dfs(dp, dp2, v, n, i, t);
	return dp2[i][t] = dfs(dp, dp2, v, n, i, t) + dfs2(dp, dp2, v, n, i-1, t);
}

int dfs(vector<vector<int>> &dp, vector<vector<int>> &dp2, const vector<int> &v, const int &n, int i, int s) {
	if (s <= 0) return 0;
	if (dp[i][s] != -1) return dp[i][s];
	if (v[i] > s) return dp[i][s] = 0;
	if (v[i] == s) return dp[i][s] = i+1;
	int t = s - v[i];
	if (i == 0) return dp[i][s] = 0;
	return dp[i][s] = dfs2(dp, dp2, v, n, i-1, t);
}

