    dp[0][0] = 1;

    auto get = [&](int i, int j) -> mint {
        return dp[i][j];
    };

    auto set = [&](int i, int j, mint v) {
        if (j > s) return;
        dp[i][j] += v;
    };

    rep(i, n) {
        rep(j, s + 1) {
            mint prev = get(i, j);
            set(i + 1, j, prev);
            set(i + 1, j + v[i], prev);
        }
        if (i != 0) {
            set(i + 1, 0, 1);
            set(i + 1, v[i], 1);
        }
    }

    mint ans = 0;
    rep(i, n) {
        ans += dp[i + 1][s];
    }
    cout << ans << endl;
