    //1方向につなぐ
    int num=es.size();
    Baseedge<T>* newedge = new Biedge<T>(v1,v2,len,cost,num);
    es.push_back(newedge);
    vs[v1].edges.insert(num);
    vs[v2].edges.insert(num);
  }
