void IO::write(double x)
{
    const double eps = pow(10, -precision - 2);
    if (x == 0) {
        putch('0'), putch('.');
        for (int i = 1; i <= precision; ++i)
            putch('0');
        return;
    }
    if (x < 0)
        putch('-'), x = -x;
    LLL n = pow(10, precision);
    double res = (LLL)(x * n + 0.5) / (n * 1.0);
    LLL y = LLL(res * n + eps) % n;
    if (precision) {
        write(LLL(res + eps), '.');
        int sta[20], p = 0;
        for (; p < precision; y /= 10)
            sta[++p] = y % 10;
        for (int i = p; i >= 1; i--)
            putch(sta[i] ^ 48);
    } else
        write(LLL(res + eps));
}
