int s;
const int nax=3005;
ll mod=998244353;
int a[nax];
ll fun(int st, int end){
    if(st == end){
        return a[st]==s;
    }
    int mid=(st+end)/2;
    ll ans=(fun(st,mid)+fun(mid+1,end))%mod;
    int n=end-st+1;
    ll dp[n][s+1];

    for(int i=mid+1;i<=end;i++){
        for(int j=0;j<=s;j++){

            if(j==0){
                dp[i-st][j]=1; continue;
            }
            if(i==mid+1){
                if(a[i]==j) dp[i-st][j]=1;
                else dp[i-st][j]=0;
            }
            else{
                dp[i-st][j]=(dp[i-1-st][j]+(a[i]<=j ? dp[i-1-st][j-a[i]] : 0))%mod;
            }
        }
    }
    for(int i=mid;i>=st;i--){
        for(int j=0;j<=s;j++){
            if(j==0){
                dp[i-st][j]=1; continue;
            }
            if(i==mid){
                if(a[i]==j) dp[i-st][j]=1;
                else dp[i-st][j]=0;
            }
            else{
                dp[i-st][j]=(dp[i+1-st][j]+(a[i]<=j ? dp[i+1-st][j-a[i]] : 0))%mod;
            }
        }
    }
    ll t1[s+1]={0};
    for(int j=0;j<=s;j++){
        for(int i=mid+1;i<=end;i++){
            t1[j]=(t1[j]+dp[i-st][j])%mod;
        }
    }
    for(int j=0;j<=s;j++){
        ll g=0;
        for(int i=mid;i>=st;i--){
            g=(g+dp[i-st][j])%mod;
        }
        ans=(ans+g*t1[s-j])%mod;
    }
    return ans;
}

