constexpr int MOD = 998244353;

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N, S;
  cin >> N >> S;

  vector<int> A(N);
  F0R(i, N) {
    cin >> A[i];
  }

  // 初期状態は全部足す（true）
  vector<bool> use(N, true);
  Fp<MOD> result(0);

  // 全パターン探し、その整数列のindexの範囲[min,max]を見ていく
  int idx = 0;
  int sum = 0;
  int min = 0;
  while (true) {

    if (use[idx]) {
      sum += A[idx];

      if (sum >= S) {

        // 整数列が見つかった
        if (sum == S) {

          // この整数列の範囲[min,max]を含むL,Rのパターン数
          result += Fp<MOD>(min + 1) * Fp<MOD>(N - idx);

          // Debug: 整数列を出力
#if 0
          FOR(i, min, idx + 1) {
            if (use[i]) {
              cout << A[i] << '+';
            }
          }
          cout << " = " << S;
          cout << " P" << (Fp<MOD>(min + 1) * Fp<MOD>(N - idx)) << '\n';
#endif

        }

        // この数値は足さない
        use[idx] = false;
        sum -= A[idx];
        if (min == idx) {
          min++;
        }
      }
      else {

        // この数値は足す
      }
    }

    // 終端？
    if (++idx > N - 1) {
#if 0
      cout << "End of range\n";
      F0R(i, N) {
        cout << (use[i] ? '+' : '.');
      }
      cout << '\n';
#endif

      // 最後に足した数値まで戻り、それを足さないようにする
      while (--idx >= 0) {
        if (use[idx]) {
          break;
        }
        // それ以降の数値は全部足すように
        use[idx] = true;
      }
      if (idx < 0) {
        break;
      }

      use[idx] = false;
      sum -= A[idx];
      if (min == idx) {
        min++;
      }
    }
  }

  cout << result;
}

