	ll ans = 0;
	v[0][a[0]] = 1;
	for (int i = 1; i < N; i++) {
		if (a[i] == S) {
			ans = mod_add(ans, mod_multi(i + 1, N - i));
		}
		else if (a[i] < S) {
			ans = mod_add(ans, mod_multi(v[i - 1][S - a[i]], N - i));
		}
		for (int j = 1; j <= S; j++) {
			v[i][j] = v[i - 1][j];
		}
		for (int j = a[i] + 1; j <= S; j++) {
			v[i][j] = mod_add(v[i][j], v[i - 1][j - a[i]]);
		}
		if (a[i] <= S) {
			v[i][a[i]] = mod_add(v[i][a[i]], i + 1);
		}
	}

	cout << ans << endl;

