using Mint = ModInt<MOD>;
//Template by yosupo
const int MN = 1'000'000;
Mint fact[MN], iFac[MN];

void first() {
    fact[0] = Mint(1);
    for (int i = 1; i < MN; i++)
        fact[i] = fact[i - 1] * Mint(i);
    iFac[MN - 1] = fact[MN - 1].inv();
    for (int i = MN - 1; i >= 1; i--) {
        iFac[i - 1] = iFac[i] * Mint(i);
    }
    assert(fact[2345] * iFac[2345] == Mint(1));
}
Mint C(int n, int k) {
    if (n < k || k < 0)
        return Mint(0);
    return fact[n] * iFac[k] * iFac[n - k];
}


int N, S, A[101010];
Mint dp[3030][3030];

void solve() {
    first();
    Mint ans = 0;

    FOR(i, 1, N + 1) {
        int a = A[i - 1];
        FOR(s, 1, S + 1) {
            if (s == a && s != S) {
                dp[i][s] = dp[i - 1][s] + i;
            } else if (s == a && s == S) {
                dp[i][s] = i;
            } else if (s == S && s - a > 0) {
                dp[i][s] = dp[i - 1][s - a];
            } else if (s - a > 0)
                dp[i][s] = dp[i - 1][s] + dp[i - 1][s - a];
            else {
                dp[i][s] = dp[i - 1][s];
            }
            //       cerr << dp[i][s] << " ";
        }
        // cerr << endl;
    }
    FOR(i, 1, N + 1) {
        ans += dp[i][S] * (N - i + 1);
    }
    cout << ans << endl;
}

