// 形式的冪級数ライブラリ
struct formal_series {
    vector<ll> coeff;
    ll pdiv = 998244353LL; // 適宜変更のこと、インスタンス生成時以外で変更したときの動作は未定義
    formal_series(const ll x = 0): coeff(1, x) {}
    formal_series(const initializer_list<ll> &x): coeff(x) {}
    formal_series(const vector<ll> &x): coeff(x) {}
    size_t size() const { return coeff.size(); }
    void resize(size_t deg) { coeff.resize(deg, 0); }
    formal_series pow(size_t n, size_t deg) const {
        if (n == 0) return formal_series(1);
        if (n == 1) return formal_series(coeff);
        if (n < 0) return this->pow(-n, deg).inv(deg);
        vector<ll> rs = {1};
        vector<ll> bs = coeff;
        for (size_t mask = n; mask; mask >>= 1) {
            if (mask & 1) {
                rs = convolve(bs, rs, pdiv);
                if (rs.size() > deg) rs.resize(deg);
            }
            bs = convolve(bs, bs, pdiv);
            if (bs.size() > deg) bs.resize(deg);
        }
        rs.resize(deg);
        return formal_series(rs);
    }
    formal_series inv(size_t deg) const {
        assert(coeff.front() != 0);
        vector<ll> rs = {modinv(coeff.front(), pdiv)};
        for (size_t i = 1; i < deg; i *= 2) {
            auto rs2 = rs; for (ll &rsi : rs2) (rsi *= 2) %= pdiv;
            auto rss = convolve(rs, rs, pdiv);
            vector<ll> as(i*2, 0);
            REP(j, min<ll>(i*2, coeff.size())) as[j] = (coeff[j] % pdiv + pdiv) % pdiv;
            auto rcv = convolve(rss, as, pdiv);
            rs .resize(i*2, 0);
            rs2.resize(i*2, 0);
            rcv.resize(i*2, 0);
            for (size_t j = 0; j < i*2; j++) {
                rs[j] = (rs2[j] - rcv[j] + pdiv) % pdiv;
            }
        }
        rs.resize(deg);
        return formal_series(rs);
    }
    formal_series operator* (const formal_series &a) const { assert(pdiv == a.pdiv); auto f = formal_series(convolve(coeff, a.coeff, pdiv)); f.resize(max(this->size(), a.size())); return f; }
    formal_series& operator*= (const formal_series &a) { return *this = *this * a; }
    formal_series& operator+= (const formal_series &a) { assert(pdiv == a.pdiv); this->resize(max(this->size(), a.size())); REP(i, min(this->size(), a.size())) (this->coeff[i] += a.coeff[i]) %= pdiv; return *this; }
    formal_series operator+ (const formal_series &a) const { formal_series rs = *this; rs += a; return rs; }
    formal_series& operator-= (const formal_series &a) { assert(pdiv == a.pdiv); this->resize(max(this->size(), a.size())); REP(i, min(this->size(), a.size())) (this->coeff[i] += pdiv - a.coeff[i]) %= pdiv; return *this; }
    formal_series operator- (const formal_series &a) const { formal_series rs = *this; rs -= a; return rs; }
    formal_series operator/ (const formal_series &a) const { assert(pdiv == a.pdiv); return *this * a.inv(min(this->size(), a.size())); }
    formal_series operator/= (const formal_series &a) { return *this = *this / a; }
};
formal_series operator"" _fs(unsigned long long _x) { return formal_series(_x); }

// WARNING: [a, b)
formal_series fetch(const vector<formal_series> &v, ll l, ll r, ll x, ll y, ll i) {
    if (r <= x || y <= l) return 1_fs;
    if (l <= x && y <= r) return v[i];
    ll z = (x+y) / 2;
    formal_series t1 = fetch(v, l, r, x, z, i*2+1);
    formal_series t2 = fetch(v, l, r, z, y, i*2+2);
    return t1 * t2;
}

