	    //continue the interval, or start it now
	    dp[i+1][j][1] += dp[i][j][0] + dp[i][j][1];
	    dp[i+1][j][1] %= mod;

	    //end the interval
	    dp[i+1][j][2] += dp[i][j][0] + dp[i][j][1] + dp[i][j][2];
	    dp[i+1][j][2] %= mod;

