const int mod = 998244353;

void add_self (int & a, int b) {
	a += b;
	if (a >= mod) a -= mod;
}

int mul (int a, int b) {
	return (ll) a * b % mod;
}

int main() {
	ios_base::sync_with_stdio (false);
	cin.tie (0); cout.tie (0);
	int n, s;
	cin >> n >> s;
	vector < int > a (n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	vector < vector < int > > dp (n + 1, vector < int > (s + 1));
	// dp[i][j] = Sum of left-endpoints of all segments ending at i
	// 				and having weight j
	// vector < int > dp2 (s + 1);
	for (int i = 1; i <= n; i++) {
		for (int j = 0; j <= s; j++) {
			dp[i][j] = dp[i - 1][j];
		}
		add_self (dp[i][a[i - 1]], i);
		for (int j = a[i - 1] + 1; j <= s; j++) {
			add_self (dp[i][j], dp[i - 1][j - a[i - 1]]);
		}
	}
	int answer = 0;
	for (int i = 1; i <= n; i++) {
		add_self (answer, dp[i][s]);
	}
	cout << answer << endl;
	return 0;
}

