long long ssou(long long *pp,int l,int r)
{
	long long sum=pp[s];
	if(l==r) return sum;
	long long pk[3333];
	for(int i=0; i<=s; i++) if(i<pi[r])
		pk[i]=pp[i];
	else pk[i]=(pp[i]-pk[i-pi[r]]+p)%p;
	sum=(sum+ssou(pk,l,r-1))%p;
	return sum;
}

long long sou(long long *pp,int l,int r)
{
	long long sum=pp[s];
	if(l==r) return sum;
	long long pk[3333];
	for(int i=0; i<=s; i++) if(i<pi[l])
		pk[i]=pp[i];
	else pk[i]=(pp[i]-pk[i-pi[l]]+p)%p;
	sum=(sum+sou(pk,l+1,r))%p;
	for(int i=0; i<=s; i++) if(i<pi[r])
		pk[i]=pp[i];
	else pk[i]=(pp[i]-pk[i-pi[r]]+p)%p;
	sum=(sum+ssou(pk,l,r-1))%p;
	return sum;
}

