    dp_L[0][0] = 1; 
    for(int i = 0; i < N; i++){
        for(int s = MAX; s >= 0; s--){
            if(s + A[i] > MAX) continue; 
            dp_L[i+1][s] = (dp_L[i+1][s] + dp_L[i][s]) % MOD;
            dp_L[i+1][s + A[i]] = (dp_L[i+1][s + A[i]] + dp_L[i][s]) % MOD;
        }
    }

    dp_R[N][0] = 1;
    for(int i = N; i > 0; i--){
        for(int s = MAX; s >= 0; s--){
            if(s + A[i] > MAX) continue; 
            dp_R[i-1][s] = (dp_R[i-1][s] + dp_R[i][s]) % MOD;
            dp_R[i-1][s + A[i]] = (dp_R[i-1][s + A[i]] + dp_R[i][s]) % MOD;
        }
    }

    i64 ans = 0;
    for(int l = 1; l < N; l++){
        for(int r = l; r < N; r++){
            i64 res = dp_L[N][S]  - (dp_L[l-1][S] + dp_R[r+1][S]);
            if(res < 0) res += MOD;
            ans = (ans + res) % MOD;  
        }
    }

    //cout << dp_L[N][S] << endl;
    cout << ans << endl;
}

