struct modint {
    ll x;
    constexpr modint(ll x = 0) : x((x % MOD + MOD) % MOD) {
    }
    ll value() const {
        return x;
    }
    constexpr modint operator-() const {
        return modint(-x);
    }
    constexpr modint& operator+=(const modint a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    constexpr modint& operator-=(const modint a) {
        if ((x += MOD - a.x) >= MOD) x -= MOD;
        return *this;
    }
    constexpr modint& operator*=(const modint a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    constexpr modint operator+(const modint a) const {
        modint res(*this);
        return res += a;
    }
    constexpr modint operator-(const modint a) const {
        modint res(*this);
        return res -= a;
    }
    constexpr modint operator*(const modint a) const {
        modint res(*this);
        return res *= a;
    }
    constexpr modint pow(ll t) const {
        if (t == 0) return 1;
        modint a = pow(t >> 1);
        a *= a;
        if (t % 2 == 1) a *= *this;
        return a;
    }
    constexpr modint inv() const {
        return pow(MOD - 2);
    }
    constexpr modint& operator/=(const modint a) {
        return (*this) *= a.inv();
    }
    constexpr modint operator/(const modint a) const {
        modint res(*this);
        return res /= a;
    }
};

