bool isprime(ll n)
{
  if (n == 0 || n == 1)
    return false;
  for (ll i = 2; i * i <= n; ++i)
    if (n % i == 0)
      return false;
  return true;
}

const int MAX = 2000010;
long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit()
{
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++)
  {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算
long long COM(int n, int k)
{
  if (n < k)
    return 0;
  if (n < 0 || k < 0)
    return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long extGCD(long long a, long long b, long long &x, long long &y)
{
  if (b == 0)
  {
    x = 1;
    y = 0;
    return a;
  }
  long long d = extGCD(b, a % b, y, x);
  y -= a / b * x;
  return d;
}
// 負の数にも対応した mod (a = -11 とかでも OK)
inline long long mod(long long a, long long m)
{
  return (a % m + m) % m;
}

// 逆元計算 (ここでは a と m が互いに素であることが必要)
long long modinv(long long a, long long m)
{
  long long x, y;
  extGCD(a, m, x, y);
  return mod(x, m); // 気持ち的には x % m だが、x が負かもしれないので
}
ll GCD(ll a, ll b)
{

  if (b == 0)
    return a;
  return GCD(b, a % b);
}

typedef vector<ll> vec;
typedef vector<vec> mat;

mat mul(mat &A, mat &B)
{
  mat C(A.size(), vec((int)B[0].size()));
  for (int i = 0; i < A.size(); ++i)
  {
    for (int k = 0; k < B.size(); ++k)
    {
      for (int j = 0; j < B[0].size(); ++j)
      {
        C[i][j] = (C[i][j] + A[i][k] % MOD * B[k][j] % MOD) % MOD;
      }
    }
  }
  return C;
}
mat matPow(mat A, ll n)
{
  mat B(A.size(), vec((int)A.size()));

  for (int i = 0; i < A.size(); ++i)
  {
    B[i][i] = 1;
  }

  while (n > 0)
  {
    if (n & 1)
      B = mul(B, A);
    A = mul(A, A);
    n >>= 1;
  }
  return B;
}

template <class TYPE>
struct Fenwick
{
  int N;
  vector<ll> bit;

  Fenwick() : N(0) {}
  Fenwick(int n) : N(n), bit(N + 1, 0) {}

  void add(int i, ll x)
  {
    ++i; //0-indexedを避けるために加算
    while (i <= N)
    {
      bit[i] += x;
      i += (i & -i);
    }
  }

  ll sum(int i)
  {
    ll res = 0;
    while (i > 0)
    {
      res += bit[i];
      i -= (i & -i);
    }
    return res;
  }

  ll range(int i, int j)
  {
    return sum(j) - sum(i);
  }

  ll get(int i)
  {
    return sum(i) - sum(i - 1);
  }
};

const ll mod2 = 998244353;
//0:まだLが固定されていない
//1:L固定, Rが固定されていない
//2:L,R固定
ll dp[3010][3010][3];
int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(4);

  int N, S;
  cin >> N >> S;

  vector<int> a(N);
  REP(i, N)
  {
    cin >> a[i];
  }
  dp[0][0][0] = 1;
  for (int i = 0; i < N; i++)
  {
    for (int j = 0; j <= S; j++)
    {
      if (j - a[i] >= 0)
      {
        dp[i + 1][j][1] += dp[i][j - a[i]][0];
        dp[i + 1][j][1] += dp[i][j - a[i]][1];
        dp[i + 1][j][1] %= mod2;
        dp[i + 1][j][2] += dp[i][j - a[i]][1];
        dp[i + 1][j][2] += dp[i][j - a[i]][0];
        dp[i + 1][j][2] %= mod2;
      }

      dp[i + 1][j][0] += dp[i][j][0];
      dp[i + 1][j][0] %= mod2;

      // L固定済, xiを加えない
      dp[i + 1][j][1] += dp[i][j][0];
      dp[i + 1][j][1] += dp[i][j][1];
      dp[i + 1][j][1] %= mod2;

      // L, R固定
      dp[i + 1][j][2] += dp[i][j][0];
      dp[i + 1][j][2] += dp[i][j][1];
      dp[i + 1][j][2] %= mod2;
    }
  }

  int ans = 0;
  for (int i = 0; i <= N; i++)
  {
    ans += dp[i][S][2];
    ans %= mod2;
    //cout << dp[i][S][2] << endl;
  }
  cout << ans << endl;
  return 0;
}

