	  CL_new[s_new] += CL[s];
	  CL_new[s_new] %= NUM;
	}
	else if(s_new == S) {
	  ans += CL[s] * (N - i);
	  ans %= NUM;
	}
      }
      CL.swap(CL_new);    
    }

