const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, tot, dp[3][3005][3005];
vl as;
const ll mod = 998244353;

void solve(){
    as = vl(n);
    rep(i, n) in1(as[i]);

    dp[0][0][0] = 1;
    For(i1, 1, n + 1) rep(i2, tot + 1){
        dp[0][i1][i2] += dp[0][i1 - 1][i2];
        dp[1][i1][i2] += dp[0][i1 - 1][i2] + dp[1][i1 - 1][i2];
        dp[2][i1][i2] += dp[0][i1 - 1][i2] + dp[1][i1 - 1][i2] + dp[2][i1 - 1][i2];

        ll a = as[i1 - 1];
        if (i2 - a >= 0){
            dp[1][i1][i2] += dp[0][i1 - 1][i2 - a] + dp[1][i1 - 1][i2 - a];
            dp[2][i1][i2] += dp[0][i1 - 1][i2 - a] + dp[1][i1 - 1][i2 - a];
        }
        rep(j, 3) dp[j][i1][i2] %= mod;
    }

    prl(dp[2][n][tot]);
}

