                dp[i+1][s+A[i]][1] += dp[i][s][1];
                dp[i+1][s+A[i]][2] += (dp[i][s][1]*(N-i))%MOD;//iをRとする
            }

            //from2
            dp[i+1][s][2] += dp[i][s][2];//Rが決まっているから、これ以上足せない
