/* first we need to know all subseqs (begin and end) with
 * sum(l,r)==s.
 * Then we cal calc number of pairs (idxL,idxR) including these.
 * for a given seq of x[L]..x[R] there are L posibilities for the left bound, and n-R for the right,
 * hence L*(n-R) pairs.
 * How to find all subseqs (begin and end) with sum==s?
 * Two pointer.
 */
void solve() {
	cini(n);
	cini(s);
	cinai(a, n);

	set<pii> seqs;
	int L = 0;
	int R = 0;
	int sum = 0;
	while (L < n) {
		while (R < n && sum < s) {
			sum += a[R];
			R++;
		}

		if (sum == s) {
			seqs.insert( { L, R });
		}

		while (L < n && sum > s) {
			sum -= a[L];
			L++;
		}

		if (sum == s) {
			seqs.insert( { L, R });
			sum -= a[L];
			L++;
		}

		if (sum < s && R >= n)
			break;
	}

	int ans = 0;
	for (pii p : seqs) {
		//cout << "L=" << p.first << " R=" << p.second << endl;
		ans += (p.first + 1) * (n - p.second + 1);
		ans %= 998244353;
	}
	cout << ans << endl;
}

int main() {
	cin.tie(nullptr);
	std::ios::sync_with_stdio(false);
	solve();
}

