void solve(long long N, long long S, std::vector<long long> A)
{
  vector<vector<mint<>>> dp(N + 1, vector<mint<>>(S + 1));

  mint<> ans = 0;
  for (int i = 1; i <= N; i++)
  {
    for (int j = 0; j < S; j++)
    {

      dp[i][j] += dp[i - 1][j];
      int nxt = j + A[i - 1];
      if (nxt > S)
        continue;
      if (j == 0)
      {
        dp[i][nxt] += i;
      }
      else
      {
        dp[i][nxt] += dp[i - 1][j];
      }
    }
    ans += dp[i][S] * (N - i + 1);
  }
  cout << ans << endl;
}

int main()
{
  cout << setprecision(10);
  long long N;
  scanf("%lld", &N);
  long long S;
  scanf("%lld", &S);
  std::vector<long long> A(N);
  for (int i = 0; i < N; i++)
  {
    scanf("%lld", &A[i]);
  }
  solve(N, S, std::move(A));
  return 0;
}

