void solve() {
    constexpr i64 mod = 998244353;

    i64 N,S;
    cin >> N >> S;
    vector<i64> A(N);
    rep(i,0,N){
        cin >> A[i];
    }

    constexpr i64 maxn=3001,maxs=3001;
    static fp<mod> memo[maxn][maxs][3]; // 0: 両側未確定, 1: 左側確定, 2: 両側確定
    static bool done[maxn][maxs][3];
    function<fp<mod>(i64,i64,i64)> rec=[&](i64 i,i64 s,i64 p){
        auto& res=memo[i][s][p];
        if(done[i][s][p]) return res;
        done[i][s][p]=true;

        if(i==N){
            return res=(p==2) and (s==S?1:0);
        }

        if(p==2){
            res=rec(i+1,s,2);
        }
        if(p==0){
            res+=rec(i+1,s,0);
            res+=rec(i+1,s,1); // iをLとする
            if(A[i]+s<=S){
                res+=rec(i+1,s+A[i],1); // iをLとして,A[i]をとる.
                res+=rec(i+1,s+A[i],2); // iをLかつRとして, A[i]をとる.
            }
        }
        if(p==1){
            res+=rec(i+1,s,1);
            res+=rec(i+1,s,2);
            if(A[i]+s<=S){
                res+=rec(i+1,s+A[i],1);
                res+=rec(i+1,s+A[i],2);
            }
        }
        return res;
    };

    cout << rec(0,0,0) << endl;
}

