    for (int i = 0; i < v.size(); ++i) 
    {
        mx = max(mx, v[i]);
        mn = min(mn, v[i]);
    }
    vv.pb(mp(mn, mx));
} 

void SubRec(int arr[], int i, int sum, vector<int>& p) 
{
    if (i == 0 && sum != 0 && dp[0][sum]) 
    { 
        p.push_back(i); 
        display(p); 
        return; 
    }
    if (i == 0 && sum == 0) 
    { 
        display(p); 
        return; 
    }
    if (dp[i-1][sum]) 
    {
        vector<int> b = p; 
        SubRec(arr, i-1, sum, b); 
    }
    if (sum >= arr[i] && dp[i-1][sum-arr[i]]) 
    { 
        p.push_back(i); 
        SubRec(arr, i-1, sum-arr[i], p); 
    } 
} 

void CntSub(int arr[], int n, int sum) 
{ 
    if (n == 0 || sum < 0) return; 
    dp = new bool*[n]; 
    for (int i=0; i<n; ++i) 
    { 
        dp[i] = new bool[sum + 1]; 
        dp[i][0] = true; 
    } 
    if (arr[0] <= sum) 
       dp[0][arr[0]] = true; 
    for (int i = 1; i < n; ++i) 
        for (int j = 0; j < sum + 1; ++j) 
            dp[i][j] = (arr[i] <= j) ? dp[i-1][j] || 
                                       dp[i-1][j-arr[i]] 
                                     : dp[i - 1][j]; 
    if (dp[n-1][sum] == false) 
    {
        vv.pb({-1, -1});
        return;
    } 
    vector<int> p; 
    SubRec(arr, n-1, sum, p); 
} 

