		cin >> a[i];

	ll result = 0;
	for ( int i = 0; i < n; i++ ){
		//a[i]を使うことで数列が完成するなら、カウントする
		if ( a[i] < s ){
			if ( i != 0 )
				result = (result + dp[i-1][s-a[i]] * (n-i))%M;
		}
		else if ( a[i] == s ){
			result = (result + (i+1)*(n-i))%M;
		}

		// dpを計算
		for ( int j = 0; j <= n; j++ ){
