				if ( j > a[i] ){
					dp[i][j] = (dp[i-1][j] + dp[i-1][j-a[i]])%M;
				}
				else if ( j == a[i] ){
					dp[i][j] = (dp[i-1][j] + (i+1))%M;
				}
				else {
					dp[i][j] = dp[i-1][j];
				}
			}
		}
	}


