			next[j + a[i]][1] += dp[j][0]; // 加算あり
			// 区間を終える
			next[j][2] += dp[j][1]; // 加算なし
			next[j + a[i]][2] += dp[j][0] + dp[j][1]; // 加算あり

			next[j][0] %= MOD;
			next[j][1] %= MOD;
			next[j][2] %= MOD;
			next[j + a[i]][1] %= MOD;
			next[j + a[i]][2] %= MOD;
		}
		dp = next;
	}
	cout << dp[s][2];
	return 0;
