int n, s;
vector<int> v;

int dpl[1505][1505], dpr[1505][1505];

ll dc(int l, int r) {
    if (l == r) {
        return v[l] == s;
    }

    int m = l + r >> 1;

    // dp left, dp right
    vector<int> vl, vr;
    vl.push_back(0);
    vr.push_back(0);
    for (int i = m; i >= l; i--) vl.push_back(v[i]);
    for (int i = m + 1; i <= r; i++) vr.push_back(v[i]);

    int sl = vl.size() - 1, sr = vr.size() - 1;

    rep(i, 0, max(vl.size(), vr.size()) + 1) rep(j, 0, 1505) dpl[i][j] = dpr[i][j] = 0;
    dpl[0][0] = dpr[0][0] = 1;

    rep(i, 1, vl.size()) {
        for (int j = s; j >= 0; j--) {
            dpl[i][j] = dpl[i - 1][j];
            if (j >= vl[i]) (dpl[i][j] += dpl[i - 1][j - vl[i]]) %= mod;
        }
    }
    rep(i, 1, vr.size()) {
        for (int j = s; j >= 0; j--) {
            dpr[i][j] = dpr[i - 1][j];
            if (j >= vr[i]) (dpr[i][j] += dpr[i - 1][j - vr[i]]) %= mod;
        }
    }

    vector<ll> wsl(s + 1), wsr(s + 1);

    wsl[0] += sl, wsr[0] += sr;

    for (int i = 1; i <= sl; i++) {
        for (int j = 0; j <= s; j++) {
            (wsl[j] += 1ll * (sl - i + 1) * (dpl[i][j] - dpl[i - 1][j] + mod)) %= mod;
        }
    }
    for (int i = 1; i <= sr; i++) {
        for (int j = 0; j <= s; j++) {
            (wsr[j] += 1ll * (sr - i + 1) * (dpr[i][j] - dpr[i - 1][j] + mod)) %= mod;
        }
    }

    ll ans = 0;
    for (int i = 0; i <= s; i++) {
        ans = (ans + 1ll * wsl[i] * wsr[s - i]) % mod;
    }

    return ((ans + dc(l, m) + dc(m + 1, r)) % mod + mod) % mod;
}

