                    dp[j+A[i]] %= MOD;
                }
            }
            if(A[i] == S){
                res += (i+1) * (N-i); // L=1~i+1 R=i+1~N
                res %= MOD;
            } else if(A[i] < S){
                dp[A[i]] += (i+1); // L=1~iまでの分
                dp[A[i]] %= MOD;
            }
        }
        cout << res << endl;
    }
}

