void solver() {
    int N = input(), S = input();
    vector< i64 > A(N);
    cin >> A;

    vector< modint > dp(S);
    dp[0] = 1;

    modint ans = 0;
    rrange(l, 0, N) {
        if (S - A[l] > 0) ans += dp[S - A[l]] * (l + 1);
        if (S == A[l]) ans += modint(l + 1) * (N - l);

        rrange(i, A[l] + 1, S) {
            dp[i] += dp[i - A[l]];
        }
        if (A[l] < S) dp[A[l]] += (N - l);
    }

    cout << ans << endl;
}

