LL call(int pos,int sum,int state)
{
    if(sum == s){
        return n - (pos - 1) + 1;
    }
    if(pos == n + 1){
        return 0;
    }

    if(dp[pos][sum][state] != -1)return dp[pos][sum][state];
    LL ret = 0;
    if(state == 0){
        ret = ret + call(pos + 1,sum,state);
        if(ara[pos] + sum <= s)ret = ret + pos * call(pos + 1,sum + ara[pos],1);
