void solve(){
	constexpr int MOD = 998244353;
	auto add = [](ll x, ll y) { return (x + y) % MOD; };
	auto mul = [](ll x, ll y) { return (x * y) % MOD; };

	int n, s;
	cin >> n >> s;

	vector<int> arr(n);
	for(auto& i: arr) cin >> i;

	ll dp[n + 1][s + 1] = {};

	for(int i = 1; i <= n; ++i){
		++dp[i - 1][0];
		for(int j = 0; j <= s; ++j){
			dp[i][j] += dp[i - 1][j];
			if(arr[i - 1] <= j) dp[i][j] += dp[i - 1][j - arr[i - 1]];
			dp[i][j] %= MOD;
		}
	}

	#ifdef SANYAM1101
	cerr << "DP Table" << "\n";
	for(int i = 0; i <= n; ++i)
		for(int j = 0; j <= s; ++j)
			cerr << dp[i][j] << " \n"[j == s];
	#endif

	ll ans = 0;

	for(int i = 1; i <= n; ++i)
		ans = add(ans, mul(dp[i][s] - dp[i - 1][s], n - i + 1));

	cout << ans << "\n";
}

