template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
      x = (int) (1LL * x * p.x % mod);
      return *this;
  }

  ModInt &operator/=(const ModInt &p) {
      *this *= p.inverse();
      return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
      int a = x, b = mod, u = 1, v = 0, t;
      while(b > 0) {
          t = a / b;
          swap(a -= t * b, b);
          swap(u -= t * v, v);
      }
      return ModInt(u);
  }

  ModInt pow(int64_t n) const {
      ModInt ret(1), mul(x);
      while(n > 0) {
          if(n & 1) ret *= mul;
          mul *= mul;
          n >>= 1;
      }
      return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
      return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
      int64_t t;
      is >> t;
      a = ModInt< mod >(t);
      return (is);
  }

  static int get_mod() { return mod; }
};

using modint = ModInt< MOD >;

const int MAX_N = 3010;

int N, S;
V<> A;

int dp[MAX_N][MAX_N][3];

// i 番目を見ていて、現在の値が j
// ステータスが k の時の f(L, R) の和
// k = 0: まだ左端を選んでいない
// k = 1: 左端を選んだが右端は選んでいない
// k = 2: 右端も選んだ
modint dfs(int i, int j, int k) {
    if(i >= N) {
        return (k == 2 && j == S) ? 1 : 0;
    }

    int& val = dp[i][j][k];
    if(~val) { return val; }
    modint ret(0);

    if(k == 0) {
        if(j + A[i] <= S) {
            // ここを左端にする
            ret += dfs(i + 1, j + A[i], 1) * modint(i + 1);
            // ここを左端であり右端にする（要素 1 つ）
            ret += dfs(i + 1, j + A[i], 2) * modint(i + 1) * modint(N - i);
        }
    }
    else if(k == 1) {
        if(j + A[i] <= S) {
            // ここを右端にする
            ret += dfs(i + 1, j + A[i], 2) * modint(N - i);
            // 右端にはしないが、取りはする
            ret += dfs(i + 1, j + A[i], k);
        }
    }
    // まだ選ばない／全て選択済み
    ret += dfs(i + 1, j, k);

    val = ret.x;

    return ret;
}

