mint factMod(lint n) {
	if (n == 0)
	{
		return 1;
	}
	mint ans = 1;
	while (n > 1) {
		ans *= n;
		n--;
	}
	return ans;
}
mint powMod(mint x, lint y)
{
	if (x.n <= 1)
	{
		return x;
	}
	if (y == 0)
	{
		return 1;
	}
	else if (y == 1)
	{
		return x;
	}
	else if (y % 2 == 0)
	{
		mint tmp = powMod(x, y / 2);
		return tmp * tmp;
	}
	else
	{
		mint tmp = powMod(x, y / 2);
		return tmp * tmp * x;
	}
}
mint modinv(mint n)
{
	return powMod(n, mod - 2);
}

void preCalcInv(lint up)
{
	invtbl.resize(up + 1);
	invtbl[1] = 1;
	repb(a, 2, up)
	{
		invtbl[a] = invtbl[a] = mod - invtbl[mod % a] * (mod / a);
	}
}

mint operator/(mint a, mint b)
{
	if (b.n < invtbl.size())
	{
		a *= invtbl[b.n];
	}
	else
	{
		a *= modinv(b);
	}
	return a;
}
mint& operator/=(mint& a, mint b)
{
	a = a / b;
	return a;
}


auto parr(lint n)
{
	vector<nval<lint>> d;
	lint n_ = n;
	for (lint i = 2; i * i <= n; i++)
	{
		if (n_ % i == 0)
		{
			d.push_back(nval<lint>(1, i));
			n_ /= i;
			while (n_ % i == 0)
			{
				n_ /= i;
				d.back().n++;
			}
		}
	}
	if (n_ > 1)
	{
		d.push_back(nval<lint>(1, n_));
	}
	return d;
}

