		dp[0] = mod(dp[0] + 1, MOD);

		for(int j = s; j >=0; --j){
			if(j + a[i] <= s) dp[j + a[i]] = mod(dp[j + a[i]] + dp[j], MOD);
		}
		ans = mod(ans + dp[s], MOD);
	}
	cout<< ans << endl;
}

