    for(int i = 1; i <= n; i++) {
        dp[i][a[i]] = i;

        for(int j = 0; j <= s; j++) {
            dp[i][j] = (dp[i][j] + dp[i-1][j]) % mod;
            if(j >= a[i]) dp[i][j] = (dp[i][j] + dp[i-1][j-a[i]]) % mod;
