int f(int L, int R, vector<int> &A, int S){
  int ans;
  if (L == R){
    if (A.at(L - 1) == S){
      ans = 1;
    }
    else{
      ans = 0;
    }
  }
  else if (S <= 0){
    ans = 0;
  }
  else{
    if (A.at(R - 1) == S){
      ans = f(L, R - 1 , A, S) + f(L, R - 1, A, S - A.at(R - 1)) + 1;
    }
    else{
      ans = f(L, R - 1 , A, S) + f(L, R - 1, A, S - A.at(R - 1));
    }
  }
  return ans;
}

