struct fpoint {ld x; ld y;
    bool operator<(const fpoint& p) const{
        if (x == p.x) return y < p.y;
        return x < p.x;
    }

    bool operator==(const fpoint& p) const{
        if (p.x - EPS < x && x < p.x + EPS
            && p.y - EPS < y && y < p.y + EPS) return true;
        return false;
    }

    bool operator!=(const fpoint& p) const{
        if (p.x - EPS > x || x > p.x + EPS
            || p.y - EPS > y || y > p.y + EPS) return true;
        return false;
    }

    fpoint& operator+=(const ld a){
        x += a, y += a;
        return *this;
    }

    fpoint& operator-=(const ld a){
        x -= a, y -= a;
        return *this;
    }

    fpoint& operator*=(const ld a){
        x *= a, y *= a;
        return *this;
    }

    fpoint& operator/=(const ld a){
        x /= a, y /= a;
        return *this;
    }

    fpoint& operator+=(const fpoint p){
        x += p.x, y += p.y;
        return *this;
    }

    fpoint& operator-=(const fpoint p){
        x -= p.x, y -= p.y;
        return *this;
    }

    fpoint& operator*=(const fpoint p){
        x *= p.x, y *= p.y;
        return *this;
    }

    fpoint& operator/=(const fpoint p){
        x /= p.x, y /= p.y;
        return *this;
    }

    bool is_zero(){
        fpoint z = {0, 0};
        return z == *this;
    }

    fpoint operator+(const fpoint p) const {return fpoint(*this) += p;}
    fpoint operator-(const fpoint p) const {return fpoint(*this) -= p;}
    fpoint operator*(const fpoint p) const {return fpoint(*this) *= p;}
    fpoint operator/(const fpoint p) const {return fpoint(*this) /= p;}
    fpoint operator+(const ld a) const {return fpoint(*this) += a;}
    fpoint operator-(const ld a) const {return fpoint(*this) -= a;}
    fpoint operator*(const ld a) const {return fpoint(*this) *= a;}
    fpoint operator/(const ld a) const {return fpoint(*this) /= a;}
};

