    cost: if link cost is fixed, put positive integer
          otherwise -1
    directed: if directed true, olse false
    offset: if the given vertex is 1-indexed, -1.
*/

void solve(){
    // generate_array(size, min, max);
    in2(n, m);
    vmi3 dp(3, vmi2(n + 1, vmi(m + 1, 0)));
    read_vector(n, as);

    dp[0][0][0] = 1;
    For(i, 1, n + 1) rep(v, m + 1){
        dp[0][i][v] = dp[0][i - 1][v];
        dp[1][i][v] = dp[0][i - 1][v] + dp[1][i - 1][v];
        dp[2][i][v] = dp[0][i - 1][v] + dp[1][i - 1][v] + dp[2][i - 1][v];

