        if (v - nxt >= 0){
            dp[1][i][v] += dp[0][i - 1][v - nxt] + dp[1][i - 1][v - nxt];
            dp[2][i][v] += dp[0][i - 1][v - nxt] + dp[1][i - 1][v - nxt];
