    i64 n, s;
    cin >> n >> s;
    auto a = vector<i64>(n, 0);
    for (usize i: range(n)) {
        cin >> a[i];
    }
    auto dp = vector<vector<i64>>(s + 1, vector<i64>(3));
    dp[0][0] = 1;
    for (usize i: range(n)) {
        if (a[i] > s) {
            continue;
        }
        auto dp_next = dp;
        for (usize j: range(s + 1)) {
            dp_next[j][1] += dp[j][0];
            dp_next[j][1] %= M;
            dp_next[j][2] += dp[j][0] + dp[j][1];
            dp_next[j][2] %= M;
            if (static_cast<i64>(j) + a[i] <= s) {
                dp_next[j + a[i]][1] += (dp[j][0] + dp[j][1]);
                dp_next[j + a[i]][1] %= M;
                dp_next[j + a[i]][2] += (dp[j][0] + dp[j][1]);
                dp_next[j + a[i]][2] %= M;
            }
        }
        dp = dp_next;
    }
    cout << dp[s][2] << endl;
    return 0;
}

