const long long MOD = 998244353;
void solve(long long N, long long S, std::vector<long long> A){
  ll ans=0;
  vector<vector<ll>> dp(2,vector<ll>(S+1));
  REP(N){
    ll prev=(i%2)^1;
    ll now=i%2;
    For(j,S+1){
      dp[now][j]=dp[prev][j];
    }
    For(j,S+1-A[i]){
      if(dp[prev][j]>0){
        dp[now][j+A[i]]+=(dp[prev][j])%MOD;
        dp[now][j+A[i]]%=MOD;
      }
    }
    if(A[i]<S+1){
      dp[now][A[i]]+=i+1;
      dp[now][A[i]]%=MOD;
    }
    ans+=dp[now][S];
    ans%=MOD;
  }
  cout<<ans<<endl;
}

