		for(int j = 0; j <= s; ++j) {
			dp[i][j] += dp[i - 1][j];
			if(j - a[i - 1] >= 0) {
				if(j - a[i - 1] == 0) {
					if(j == s) {
						dp[i][j] += (dp[i - 1][j - a[i - 1]] + (i - 1)) * (n - i + 1);
					} else {
						dp[i][j] += dp[i - 1][j - a[i - 1]] + (i - 1);
					}
				} else {
					if(j == s) {
						dp[i][j] += dp[i - 1][j - a[i - 1]] * (n - i + 1);
					} else {
						dp[i][j] += dp[i - 1][j - a[i - 1]];
					}
				}
			}
		}
	}
	cout << dp[n][s] << '\n';
	return 0;
}

