void solve() {
    int N, S; cin >> N >> S;
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    vector<mint> F(S+1);    // F[i]：x^iの係数

    mint ans = 0;
    for (int i = 0; i < N; i++) {
        F[0] += 1;
        vector<mint> F_copy = F;
        for (int s = 0; s <= S-A[i]; s++) {
            F[s+A[i]] += F_copy[s];
        }
        ans += F[S];
    }

    cout << ans << '\n';
}

