    int arr[n+1];
    arr[0]=0;
    for(int i=1;i<=n;i++) {
        cin>>arr[i];
    }

    int ans=0;
    int dp[n+1][s+1];
    for(int i=0;i<=n;i++) {
        for(int j=0;j<=s;j++) {
            dp[i][j]=0;
        }
    }
    for(int i=1;i<=n;i++) {
        dp[i][arr[i]]+=i;
        for(int j=0;j<=s;j++) {
            if(j+arr[i]<=s) {
                dp[i][j+arr[i]]+=dp[i-1][j];
                dp[i][j+arr[i]]%=MOD;
