            dp[i][j]+=dp[i-1][j];
            dp[i][j]%=MOD;
            //cout<<dp[i][j]<<" ";
        }
        //cout<<"\n";
        ans+=(dp[i][s]*(n-i+1));
        ans%=MOD;
        dp[i][s]=0;
    }
    cout<<ans;

