    cin >> S;
    vector<ll> A(N+1,0);
    for(ll i=0;i<N;i++){
        cin>>A[i+1]
    ;}
    ll ans=0;
    //L確定
    vector<vector<ll>> dp(N+1, vector<ll>(S+1, 0));
    for(ll i=1;i<=N;i++){
        //L=iのときを追加
        dp[i][0]++;
        if(A[i]<=S){
            dp[i][A[i]]++;
        }
        //以下、L<iのとき
        //A[i]採用する方
        for(ll j=A[i];j<=S;j++){
            dp[i][j]+=dp[i-1][j-A[i]];
            dp[i][j]%=MOD;
        ;}
        //A[i]採用しない方
        for(ll j=0;j<=S;j++){
            dp[i][j]+=dp[i-1][j];
            dp[i][j]%=MOD;
        ;}
        ans+=(dp[i][S]-dp[i-1][S])*(N-i+1);
        ans%=MOD;
    ;}
    cout<<ans<<endl;

    return 0;
}

