ll longestPrefixSuffix(string s) { 
    ll n = s.length(); 
    ll lps[n]; 
    lps[0] = 0; 
    ll len = 0, i=1;
    while (i < n){ 
        if (s[i] == s[len]){ 
            len++; 
            lps[i] = len; 
            i++; 
        } 
        else{ 
            if (len != 0) 
                len = lps[len-1]; 
            else
                lps[i] = 0,i++;
        } 
    } 
    ll res = lps[n-1]; 
    return (res > n/2)? n/2 : res; 
} 

