	vector<vector<ll>> edges(N);
	ll a, b;
	for (ll i = 1; i < N; ++i) {
		cin >> a >> b;
		--a, --b;
		edges[a].emplace_back(b);
		edges[b].emplace_back(a);
	}

	vector<rll> exclams;
	exclams.reserve(N + 1);
	exclams.emplace_back(1);
	for (ll i = 0; i < N; ++i) {
		exclams.emplace_back(exclams[i] * (i + 1));
	}

	map<pair<ll, ll>, pair<ll, rll>> counts;
	rll res;
	for (ll i = 0; i < N; ++i) {
		res = calc_count(i, -1LL, edges, counts, exclams).second;
		cout << res.get_n() << endl;
	}


	return 0;
}

