        for(int j = 3000; j >= 0; j--){
            if(j >= a[i]){
                addmod(dpl[j], dpl[j-a[i]]);
            }
            addmod(psl[j], dpl[j]);
        }
    }
    for(int i = m+1; i <= r; i++){
        for(int j = 3000; j >= 0; j--){
