  long long total = 0;
  for (int i = 0; i < N; i++){
    for (int j = S; j > A[i]; j--){
      dp[j] = (dp[j] + dp[j - A[i]]) % MOD;
    }
    if (A[i] <= S){
      dp[A[i]] = (dp[A[i]] + dp[0] + i + 1) % MOD;
    }
    total += dp[S] * (N - i) % MOD;
    dp[S] = 0;
  }
  cout << total % MOD;
}

