bool** dp;

int n;
int mod = 998244353;

// A recursive function to print all subsets with the 
// help of dp[][]. Vector p[] stores current subset. 
int printSubsetsRec(int arr[], int i, int sum, vector<Pi>& p) 
{ 
    // If we reached end and sum is non-zero. We print 
    // p[] only if arr[0] is equal to sun OR dp[0][sum] 
    // is true.
  int ans = 0;
    if (i == 0 && sum != 0 && dp[0][sum]) 
    { 
      p.push_back(MP(i, arr[i]));
      return (p[p.size() - 1].fi + 1) * (n - p[0].fi) % mod; 
    } 

    // If sum becomes 0 
    if (i == 0 && sum == 0) 
    {
      return (p[p.size() - 1].fi + 1) * (n - p[0].fi) % mod; 
    } 

    // If given sum can be achieved after ignoring 
    // current element. 
    if (dp[i-1][sum]) 
    { 
        // Create a new vector to store path 
        vector<Pi> b = p; 
        ans += printSubsetsRec(arr, i-1, sum, b) % mod, ans %= mod; 
    } 

    // If given sum can be achieved after considering 
    // current element. 
    if (sum >= arr[i] && dp[i-1][sum-arr[i]]) 
    { 
      p.push_back(MP(i, arr[i])); 
      ans += printSubsetsRec(arr, i-1, sum-arr[i], p) % mod, ans %= mod; 
    }
    return ans % mod;
} 

// Prints all subsets of arr[0..n-1] with sum 0. 
int printAllSubsets(int arr[], int n, int sum) 
{ 
    if (n == 0 || sum < 0) 
       return 0; 

    // Sum 0 can always be achieved with 0 elements 
    dp = new bool*[n]; 
    for (int i=0; i<n; ++i) 
    { 
        dp[i] = new bool[sum + 1]; 
        dp[i][0] = true; 
    } 

    // Sum arr[0] can be achieved with single element 
    if (arr[0] <= sum) 
       dp[0][arr[0]] = true; 

    // Fill rest of the entries in dp[][] 
    for (int i = 1; i < n; ++i) 
        for (int j = 0; j < sum + 1; ++j) 
            dp[i][j] = (arr[i] <= j) ? dp[i-1][j] || 
                                       dp[i-1][j-arr[i]] 
                                     : dp[i - 1][j]; 
    if (dp[n-1][sum] == false) 
    { 
        return 0; 
    } 

    // Now recursively traverse dp[][] to find all 
    // paths from dp[n-1][sum] 
    vector<Pi> p; 
    return printSubsetsRec(arr, n-1, sum, p) % mod; 
}


