ModInt<> solve() {
  ModInt<> res = 0;
  dp.assign(n + 1, vector<ModInt<>>(s + 1, 0));
  dp[0][0] = 1;
  for(int i = 0; i < n; ++i)
    for(int j = 0; j <= s; ++j) {
      if(j != s) dp[i + 1][j] += dp[i][j];
      if(j >= a[i]) {
        if(j == a[i])
          dp[i + 1][j] += i + 1;
        else
          dp[i + 1][j] += dp[i][j - a[i]];
        if(s == j) res += dp[i + 1][j] * (n - i);
      }
    }
  return res;
}

