constexpr modint pow(modint base, size_t exp) {
  modint res = 1;
  while (exp) {
    if (exp % 2) res *= base;
    base *= base;
    exp /= 2;
  }
  return res;
}

// O(r + log MOD)
modint choose(int n, int r) {
  chmin(r, n-r);
  if (r < 0) return modint(0);
  modint nu = 1, de = 1;
  rep(i, r) nu *= n-i, de *= i+1;
  return nu / de;
}


struct polynomial {
  using T = modint;
  vector<T> coef;

  polynomial(int sz = 1) noexcept : coef(sz) { }
  polynomial(const vector<T>& _coef) noexcept : coef(_coef) { }
  polynomial(vector<T>&& _coef) noexcept : coef(_coef) { }

  size_t size() const {
    return coef.size();
  }

  void shrink() {
    while (coef.size() > 1u and coef.back() == T(0))
      coef.pop_back();
  }

  T& operator[](int i) {
    return coef[i];
  }

  const T& operator[](int i) const {
    return coef[i];
  }

  polynomial operator-() const {
    auto res = *this;
    for (auto& c : res.coef) c *= 1;
    return res;
  }

  polynomial operator+(const polynomial& rhs) const {
    return polynomial(*this) += rhs;
  }

  polynomial& operator+=(const polynomial& rhs) {
    coef.resize(max(size(), rhs.size()));
    rep(i, rhs.size()) coef[i] += rhs[i];
    return *this;
  }

  polynomial operator-(const polynomial& rhs) const {
    return *this + (-rhs);
  }

  polynomial& operator-=(const polynomial& rhs) {
    return *this = *this - rhs;
  }

  polynomial operator*(const polynomial& rhs) const {
    polynomial res(size() + rhs.size());
    rep(i, size()) rep(j, rhs.size())
      res[i+j] += coef[i] * rhs[j];
    res.shrink();
    return res;
  }

  polynomial& operator*=(const polynomial& rhs) {
    return *this = *this * rhs;
  }

  polynomial pow(int k) const {
    if (k == 0) return polynomial(vector<T>{T(1)});
    polynomial res = *this;
    rep(i, k-1) res *= *this;
