int main() {

	ll N, S;
	cin >> N >> S;

	vector<ll> A(N + 1);
	repn(i, N) cin >> A[i];

	vector<vector<ll>> dp(N + 1, vector<ll>(S + 1, 0));

	repn(i, N)dp[i][0] = 1;

	repn(i, N)repn(j, S) {
		if (j < A[i]) { dp[i][j] = dp[i - 1][j]; }
		if (j == A[i]) {
			dp[i][j] = dp[i - 1][j] + i;
		}
		if (j > A[i]) {
			dp[i][j] = dp[i - 1][j] + dp[i - 1][j - A[i]];
		}

		dp[i][j] %= MOD;
	}

	ll ans = 0;

	repn(i, N) {
		ll X = dp[i][S] - dp[i - 1][S];
		X *= (N - i + 1);
		ans += X;
		ans %= MOD;
		if (ans < 0) { ans += MOD; }
	}

	cout << ans;

	system("PAUSE");

}

