	vector<int> a(n);
	rep(i, n)scanf("%d", &a[i]);
	segtree<int> tree(n, 0, plus<int>());
	rep(i, n)tree.set(i, a[i]);
	Modint ans = 0;
	auto check = [](int a, int b) {return a == b; };
	rep(i, n) {
		int ok = n - 1, ng = i - 1, mid = i;
		while (ok - ng > 1) {
			mid = (ok + ng) / 2;
			int r = tree.query(i, mid);
			if (r == s) {
				break;
			}
			else if (r > s) {
				ok = mid;
			}
			else {
				ng = mid;
			}
		}
		if (tree.query(i, mid) != s)continue;
		else ans += (i + 1) * (n - mid);
	}
