    {
        forsn(j, 1, s+1)
        {
            dp[i][j] = 0;
            dp[i][j] += dp[i-1][j];
            dp[i][j] %= MOD;
            if(j-val[i] > 0)
            {
                dp[i][j] += dp[i-1][j-val[i]];
                dp[i][j] %= MOD;
            }
            if(j-val[i] == 0) dp[i][j] += i+1;
            dp[i][j] %= MOD;
        }
    }
    ll ans = 0;
    ans += ((dp[0][s]*n)%MOD);
    ans %= MOD;
    forsn(i, 1, n)
    {
        ll tp = dp[i][s]-dp[i-1][s];
        tp %= MOD;
        if(tp < 0) tp += MOD;
        ans += ((tp*(n-i))%MOD);
        ans %= MOD;
        if(ans < 0) ans += MOD;
    }
    cout<<ans<<ln;
}

