ll f(vector<ll>& a, ll i, ll s, bool flag) {
    if(s == 0) {
        return (ll)(a.size() + 1 - i);
    }
    if(s < 0 || i == a.size())
        return 0ll;
    if(dp[i][s][flag] != -1)
        return dp[i][s][flag];
    ll ans = 0;
    if(!flag) {
        ans += f(a, i + 1, s, flag);
        ans += (ll)(i + 1) * f(a, i + 1, s - a[i], !flag);
    }
    else {
        ans += f(a, i + 1, s, flag);
        ans += f(a, i + 1, s - a[i], flag);
    }
    return dp[i][s][flag] = ans % MOD;
}

