        rep(j,S+1){
            if(a[i]+j<=S) dp[i][a[i]+j]+=dp[i+1][j];
        }
    }
    modint ans=0;
    rep(i,n){
        ans+=dp[i][S];
    }
    cout << ans << endl;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(50);
    solve();
}

