    for(int i=1;i<=n;++i){
        int t=dp[s];
        for(int j=s;j>=1;--j){//反向，不然会更新错误
            if(j==A[i])modadd(dp[j],i);
            if(j>A[i]){
                modadd(dp[j],dp[j-A[i]]);
            }
        }
        modadd(ans,modmul(dp[s]-t,n-i+1));//差分表示右端点恰好为i的时候，其和为s的多端点的和
    }
    cout<<ans;

