using T = vector<ll>;

class SegmentTree {
public:
    int bit_, N;
    vector<T> buf_;

    SegmentTree(int size) {
        N = 1;
        bit_ = 0;
        while (N < size) {
            N *= 2;
            ++bit_;
        }

        buf_.resize(N*2);
    }
    SegmentTree(vector<T>& init){
        int size = init.size();

        N = 1;
        bit_ = 0;
        while (N < size) {
            N *= 2;
            ++bit_;
        }

        buf_.resize(N*2);

        for (int i=0; i<size; ++i) buf_[N-1+i] = move(init[i]);

        for (int i=N-2; i>=0; --i) {
            merge(buf_[i*2+1], buf_[i*2+2], buf_[i]);
        }
    }

    void merge(T& a, T& b, T& res) {
        if (a.empty()) a.assign(1,1);
        if (b.empty()) b.assign(1,1);

        ntt.convolution(a,b, res);
        if (res.size() > 3001) res.resize(3001);
    }

    void update(int i, T& x) {
        i = N + i - 1;


        buf_[i] = move(x);
        while (i > 0) {
			i = (i - 1) / 2;
			merge(buf_[i*2+1], buf_[i*2+2], buf_[i]);
        }
    }

    T query(int lo, int hi) {
        T res;
        query(lo, hi, 0, 0, N, res);
        return res;
    }
    void query(int a, int b, int k, int l, int r, T& res) {
        if (r <= a || b <= l) {
            res = T(1,1);
            return;
        }

        if (a <= l && r <= b) {
            res = buf_[k];
        } else {
            T lv, rb;
            query(a, b, 2*k+1, l, (l+r)/2, lv);
            query(a, b, 2*k+2, (l+r)/2, r, rb);
			merge(lv, rb, res);
        }
    }

    void dump() {
    }
};


ll solve(int N, int S, vi& a) {

    vector<T> ax(N);
    rep(i,N){
        ax[i].assign(a[i]+1, 0);
        ax[i][0] = ax[i][a[i]] = 1;
    }
    SegmentTree st(ax);


    ll total = 0;
    rep(l,N){
        if (a[l] != S) continue;


        int left = l, right = N-left-1;

        ll cnt = 1;
        ll mag = MUL(left+1, right+1);
        total = ADD(total, MUL(cnt, mag));
    }
    repC2(l,r,N){
        int rem = S - a[l] - a[r];
        if (rem < 0) continue;
        int left = l, right = N-r-1;
        ll cnt = 0;
        if (l+1 == r) {
            cnt = (rem == 0)? 1 : 0;
        } else {
            T pat = st.query(l+1, r);
            cnt = (pat.size() > rem) ? pat[rem] : 0;
            if (cnt == 0) continue;
        }
        ll mag = MUL(left+1, right+1);
        total = ADD(total, MUL(cnt, mag));
    }
    return total;
}

