int N, S;
vector<int> A;

mint solve() {
    vector<vector<vector<mint>>> dp(N+1, vector<vector<mint>>(6500, vector<mint>(3, 0)));
    dp[0][0][0] = 1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j <= S; ++j) {
            // from 0
            dp[i+1][j][0] += dp[i][j][0];
            dp[i+1][j+A[i]][1] += dp[i][j][0] * (i+1);
            dp[i+1][j+A[i]][2] += dp[i][j][0] * (i+1) * (N-i);

            // from 1
            dp[i+1][j][1] += dp[i][j][1];
            dp[i+1][j+A[i]][1] += dp[i][j][1];
            dp[i+1][j+A[i]][2] += dp[i][j][1] * (N-i);

            // from 2
            dp[i+1][j][2] += dp[i][j][2];
        }
    }
    return dp[N][S][2];
}

