const int N = 3005;

LL dp[N][N];

int arr[N];
int n;

LL solve(int idx, int sum)
{
	if (sum == 0) return (n - idx + 1LL);
	if (idx >= n) return 0;
	if (sum < 0) return 0;
	LL &ans = dp[idx][sum];
	if (ans != -1) return ans;
	ans = 0;
	ans = (solve(idx + 1, sum) + solve(idx + 1, sum - arr[idx])) % MOD;
	return ans;
}

int main(void)
{
	memset(dp, -1, sizeof(dp));
	int s; cin >> n >> s;
	for (int i = 0; i < n; i++) cin >> arr[i];

	LL ans = 0;

	for (int i = 0; i < n; i++){
		LL temp = solve(i + 1, s - arr[i]);
		temp = (temp * (i + 1LL)) % MOD;
		ans = (ans + temp) % MOD;
	}

	cout << ans << endl;

	return 0;
}

