    ll n,s;cin>>n>>s;
    vector<ll> a(n);rep(i,n)cin>>a[i];
    vector<vector<ll>> dp1(n+1,vector<ll>(s+1,0));
    vector<vector<ll>> dp2(n+1,vector<ll>(s+1,0));
    //dp1[i][j]:N=i,S=jに対するl*(n-r+1)の和
    //dp2[i][j]:N=i,S=jに対するlの和

