                dp2[i][j]=dp2[i-1][j]+i;
            }else{
                dp1[i][j]=dp1[i-1][j]+dp2[i-1][j]+dp2[i-1][j-A];
                dp2[i][j]=dp2[i-1][j]+dp2[i-1][j-A];
            }
