        dp[i + 1][j][0] += dp[i][j][0];
        dp[i + 1][j][1] += dp[i][j][0] + dp[i][j][1];
        dp[i + 1][j][2] += dp[i][j][0] + dp[i][j][1] + dp[i][j][2];

        if (j + a[i] <= s) {
            dp[i + 1][j + a[i]][1] += dp[i][j][0] + dp[i][j][1];
            dp[i + 1][j + a[i]][2] += dp[i][j][0] + dp[i][j][1];
        }
    }
    cout << dp[n][s][2].x << endl;
}

