void build(int v, int tl, int tr) {
  if(tl == tr) {
    t[v] = arr[tl];
    return;
  }

  int tm = (tl + tr) / 2;
  build(v*2, tl, tm);
  build(v*2 + 1, tm+1, tr);
  t[v] = t[v*2] + t[v*2 + 1];
}

int sum(int v, int tl, int tr, int l, int r) {
  if(l > r)
    return 0;
  if(tl == l && tr == r)
    return t[v];

  int tm = (tl + tr) / 2;
  return ((sum(v*2, tl, tm, l, min(r,tm)) + sum(v*2 + 1, tm+1, tr, max(l,tm+1), r));
}

