lint get_sum(int now, int sum, bool is_first){
    if(sum > S){
        return 0;
    }
    if(now == N){
        return 0;
    }
    if(dp[now][sum][is_first] != -1){
        return dp[now][sum][is_first];
    }
    lint ans = get_sum(now + 1, sum, is_first);
    lint bairitu;
    if(is_first){
        bairitu = now + 1;
