map<pair<ll,ll>, int>mp;

ll thunder(ll a[], ll l, ll r, ll n, ll s, ll tsum){
    if(tsum==s){
        return ((n-r+1))%mod;
    }
    if(tsum > s){
        return 0;
    }
    if(r==n){
        return 0;
    }
    if(mp.find({r, tsum})!=mp.end()){
        return mp[{r, tsum}];
    }
    //Including this number
    ll l1 = thunder(a, l, r+1, n, s, tsum+a[r]);
    ll l2 = thunder(a, l, r+1, n, s, tsum);
    mp[{r, tsum}] = (l1+l2+mod)%mod;
    return (l1+l2+mod)%mod;
}

