const int MX = 3005, MOD = 998244353;
int N, S, mem[MX][MX][2];
vi A;

int dp(int i, int sum, bool active) {
	if (i == N + 1)
		return 0;
	if (sum > S)
		return 0;
	int& ret = mem[i][sum][active];
	if (ret != -1)
		return ret;

	ret = 0;

	if (active) {
		ret = (dp(i + 1, sum + A[i], 1) + dp(i + 1, sum, 1)) % MOD;
		if (sum + A[i] == S)
			ret = (ret + N - i + 1) % MOD;
	} else {
		assert(sum == 0);
		ret = dp(i + 1, sum, 0);
		ret = (ret + ((dp(i + 1, sum + A[i], 1) * 1LL * i) % MOD)) % MOD;
	}

	return ret;
}



