ll takemod(ll a) {
    return ((a%mod)+mod)%mod;
}

ll gcd(ll a, ll b) { 
    if (b == 0) 
        return a; 
    return gcd(b, a % b);        
}

ll fast_exp(ll base, ll expo) {
    ll res=1;
    while(expo>0) {
        if(expo&1) res=(res*base)%mod;
        base=(base*base)%mod;
        expo>>=1;}
    return res;
}

ll modinv(ll a) {
    return takemod(fast_exp(takemod(a), mod-2));
}

const int N=3005;
ll dp[N][N];
ll n,s;
ll arr[N];
ll ans;

ll dpfunc(ll index, ll val)
{
	//cout<<index<<val<<endl;
	if(index==n)
	{
		if(val==0)
			return 1;
		else
			return 0;
	}
	else if(val==0)
	{
		return n-index+1;
	}
	else
	{
		if(dp[index][val]!=-1)
			return dp[index][val];

		ll temp=0;
		if(val>=arr[index])
			temp=(temp+dpfunc(index+1,val-arr[index]))%mod;
		temp=(temp+dpfunc(index+1,val))%mod;

		dp[index][val]=temp;
		return dp[index][val];
	}
}
void solve()
{
	cin>>n>>s;
	For(i,0,n)
	{
		cin>>arr[i];
	}

	memset(dp,-1,sizeof(dp));
	ll ans=0;
	For(i,0,n)
	{
		if(arr[i]>s)
			continue;

		ll val=dpfunc(i+1,s-arr[i]);
		ans=(ans+((val*(i+1))%mod))%mod;
		//cout<<ans<<endl;
	}
	cout<<ans<<endl;	
}

