constexpr int MOD = 998244353;

ll calc(vector<vector<vll>>& dp, const vll& a, int i, int j, int k) {
    if (dp[i][j][k] != -1) { return dp[i][j][k]; }

    if (k == 0) { return dp[i][j][k] = 1; }
    if (i == j) { return dp[i][j][k] = ((a[i] == k) ? 1 : 0); }

    ll tmp = calc(dp, a, i, j - 1, k);
    if (k - a[j] >= 0) { tmp = (tmp + calc(dp, a, i, j - 1, k - a[j])) % MOD; }
    return dp[i][j][k] = tmp;
}

