T bsearch(T begin, T end, function<bool(T)> f, T targetwidth) {
  if (f(begin)) return begin;
  if (!f(end)) return end;
  while (abs(end - begin) > targetwidth) {
    T m = (begin + end) / 2;
    if (f(m)) {
      end = m;
    } else {
      begin = m;
    }
  }
  return end;
