        rep(j, S+1) dp[i+1][j] = dp[i][j];
        rep3(j, S, A[i]+1){
            dp[i+1][j] += dp[i][j-A[i]];
            dp[i+1][j] %= MOD;
        }
        if(A[i] <= S){
            dp[i+1][A[i]] += i+1;
        }
        ans += (N-i)*(dp[i+1][S]-dp[i][S]);
    }
    cout << ans << endl;
}

