void find_subsets_min_max_index(int arr[], int i, int sum, int mn, int mx) { 
    if (i == 0 && sum != 0 && dp[0][sum]) { 
        mx = max(mx, i);
        mn = min(mn, i);
        ans = (ans + (mn + 1) * (n-1 - mx + 1)) % mod;
        return; 
    } 

    if (i == 0 && sum == 0) { 
        ans = (ans + (mn + 1) * (n-1 - mx + 1)) % mod;
        return; 
    } 

    if (dp[i-1][sum]) {
        find_subsets_min_max_index(arr, i-1, sum, mn, mx); 
    } 

    if (sum >= arr[i] && dp[i-1][sum-arr[i]]) { 
        find_subsets_min_max_index(arr, i-1, sum-arr[i], min(mn, i), max(mx, i));
    } 
} 

void find_subsets(int arr[], int n, int sum) { 
    for (int i=0; i<n; ++i) { 
        dp[i][0] = true;
    }
    dp[0][arr[0]] = true;

    for (int i = 1; i < n; ++i) {
        for (int j = 1; j <= sum; ++j) {
            dp[i][j] = (arr[i] <= j) ? dp[i-1][j] || dp[i-1][j-arr[i]] : dp[i - 1][j]; 
        }
    }
    if (dp[n-1][sum] == false) {
        return; 
    } 

    find_subsets_min_max_index(arr, n-1, sum, n, -1);
} 

