ll power(ll x, ll n, ll mod) {
  ll res = 1;
  x %= mod;
  while (n) {
    if (n & 1)
      res = (res * x) % mod;
    x = (x * x) % mod;
    n >>= 1;
  }
  return res;
}

ll dp[3005][3005];
ll arr[3005];
ll n;
ll recur(ll pos, ll rem) {

  if (rem < 0) {
    return 0;
  }
  if (rem == 0) {
    return pos - 1;
  }
  if (pos == n + 1)
    return 0;

  ll &ans = dp[pos][rem];
  if (ans != -1)
    return ans;

  ans = recur(pos + 1, rem - arr[pos]) + recur(pos + 1, rem);

  if (ans >= mod)
    ans -= mod;
  return ans;
}

ll recur2(ll pos, ll rem) {

  if (rem < 0) {
    return 0;
  }
  if (rem == 0) {
    return 1;
  }
  if (pos == n + 1)
    return 0;

  ll &ans = dp[pos][rem];
  if (ans != -1)
    return ans;

  ans = recur2(pos + 1, rem - arr[pos]) + recur2(pos + 1, rem);

  if (ans >= mod)
    ans -= mod;
  return ans;
}

