    res += (n + 1) * i % mod * recur2(i + 1, s - arr[i]) % mod;
    if (res >= mod)
      res -= mod;
  }

  memset(dp, -1, sizeof(dp));
  for (ll i = 1; i <= n; i++) {
    res -= i * recur(i + 1, s - arr[i]) % mod;
    if (res < 0)
      res += mod;
  }

