template<class Type>
Type solve(Type res = Type()){
    int N,S; cin >> N >> S;
    vector<ll> A(N); for(auto& in:A) cin >> in;

    auto dp = make_v<ll>(N+1,S+1,3);
    dp[0][0][0] = 1;
    auto update = [&](ll& l,ll r){
        r %= MOD;
        l += r;
        l %= MOD;
    };
    for(int i = 0; i < N;i++){
        for(int j = 0; j <= S; j++){
            update(dp[i+1][j][0],dp[i][j][0]);
            update(dp[i+1][j][1],dp[i][j][0] + dp[i][j][1]);
            update(dp[i+1][j][2],dp[i][j][0] + dp[i][j][1] + dp[i][j][2]);

            if(j + A[i] <= S){
                update(dp[i+1][j+A[i]][1],dp[i][j][0] + dp[i][j][1]);
                update(dp[i+1][j+A[i]][2],dp[i][j][0] + dp[i][j][1]);
            }
        }
    }
    res = dp[N][S][2];
    return res;
}
