	for(i=0;i<n;++i)
	{
		if(a[i]==s)
		{
			ans=(ans+(n-i)*(i+1))%MM;
			continue;
		}
		for(j=s;j>=0;--j)
		{
			if(i>0)dp[i][j]=dp[i-1][j];
		}
		for(j=s;j>0;--j)
		{
			if(j+a[i]<s && dp[i][j]!=-1)
			{
				if(dp[i][j+a[i]]==-1)++dp[i][a[i]+j];
				dp[i][j+a[i]]+=dp[i][j];
				dp[i][j+a[i]]%=MM;
			}
			else if(j+a[i]==s && dp[i][j]!=-1)
			{
				ans+=dp[i][j]*(n-i)%MM;
				ans%=MM;
			}
		}
