            if(x & 1)
                l = f(l, elm[x++]);
            if(!(y & 1))
                r = f(elm[y--], r);
        }
        return f(l, r);
    }
};


void solve(long long n, long long s, std::vector<long long> a){

    vector<Segtree<mint>> dp(s + 1, Segtree<mint>(n, 0, [](auto x, auto y){return x + y;}, 0));
    for(int i = 0; i < n; ++i)
        if(a[i] <= s)
            dp[a[i]].set(i, i + 1);

    for(int i = 1; i < n; ++i){
        for(int j = 0; j <= s; ++j){
            i64 prev = j - a[i];
            if(prev < 0)
                continue;
            dp[j].update(i, dp[prev].get(0, i));
        }
    }
    mint ans = 0;
    for(int i = 0; i < n; ++i)
        ans += dp[s].get(i, i + 1) * mint(n - i);

    cout << ans << endl;
}


