static int64_t kRem = 998244353;

unordered_map<int64_t, int64_t> memo;

int64_t f(int i, int j, int s, vector<int>& as)
{
	int64_t idx = i * 3001LL * 3001LL + j * 3001LL + s;
	auto it = memo.find(idx);
	if (it != memo.end()) {
		return it->second;
	}

	if (i == j) {
		if (s != 0) {
			if (as[i] == s) return 1;
			else return 0;
		}
		return 1;
	}

	int64_t ans = f(i + 1, j, s, as);
	if (as[i] <= s) {
		ans += f(i + 1, j, s - as[i], as);
		ans %= kRem;
	}

	memo[idx] = ans;

	return ans;
}

int64_t dp[3001][3001][3] = {};

int main()
{
	ios_base::sync_with_stdio(false);
