	int n, s; cin >> n >> s;
	vector<int> as(n); for (auto& a : as) cin >> a;

	int64_t ans = 0;
	FOR_LT(i, 0, n) {
		FOR_LE(j, 0, s) {
			if (i == 0) continue;

			// 1 -> 1
			dp[i][j][1] = dp[i - 1][j][1];
			if (as[i] <= j) {
				dp[i][j][1] += dp[i - 1][j - as[i]][1];
				dp[i][j][1] %= kRem;
			}

			// 2 -> 2
			dp[i][j][2] = dp[i - 1][j][2];
			// 1 -> 2
			if (as[i] <= j) {
				dp[i][j][2] += dp[i - 1][j - as[i]][1];
				dp[i][j][2] %= kRem;
				dp[i][j][2] += dp[i - 1][j][1];
				dp[i][j][2] %= kRem;
			}
		}

		// 0 -> 1, 0 -> 2
		dp[i][as[i]][1] += 1;
		dp[i][as[i]][1] %= kRem;
		dp[i][as[i]][2] += 1;
		dp[i][as[i]][2] %= kRem;
		dp[i][0][1] += 1;
		dp[i][0][1] %= kRem;
		dp[i][0][2] += 1;
		dp[i][0][2] %= kRem;
	}

	cout << dp[n - 1][s][2] << endl;

	return 0;
}

