class Solution {
private:
public:
    int solve(int n, int k, vector<int>& arr) {
        //vector<vector<vector<int64>>> dp(n + 1, vector<vector<int64>>(k + 1, vector<int64>(3)));
        int64 dp[n + 1][k + 1][3] = {};
        dp[0][0][0] = 1;
