	if(pos>n)
		return 0;
	if(soma==s)
		return n-pos+1;
	int &val = memo[pos][soma];
	if(val!=-1)
		return val;
	val = sum(dp(pos+1,soma),dp(pos+1,soma+vs[pos]));
	return val;
}

