  ll &ans = dp[pos][rem];
  if (ans != -1)
    return ans;

  ans = recur(pos + 1, rem - arr[pos]) + recur(pos + 1, rem);

  if (ans >= mod)
    ans -= mod;
  return ans;
}

ll recur2(ll pos, ll rem) {

  if (rem < 0) {
    return 0;
  }
  if (rem == 0) {
    return 1;
  }
  if (pos == n + 1)
    return 0;

  ll &ans = dp[pos][rem];
  if (ans != -1)
    return ans;

  ans = recur2(pos + 1, rem - arr[pos]) + recur2(pos + 1, rem);

  if (ans >= mod)
    ans -= mod;
  return ans;
}

