        else {
            dp[i][a[i]] += modInt{i + 1};
        }
        if(i == 0){
            continue;
        }
        for(int j = 1; j < s; j++){
            if(j + a[i] == s){
                dp[i][j+a[i]] += dp[i-1][j] * modInt{n-i};
            }
            else if(j + a[i] < s){
                dp[i][j + a[i]] += dp[i - 1][j];
            }
            dp[i][j] += dp[i-1][j];
        }
    }

    modInt res{0};
    for(int i = 0; i < n; i++){
        res += dp[i][s];
