int dp(int pos,int sum)
{
    if(sum==s)
        return n-pos+1;

    if(pos==n || sum>s)
        return 0;

    int &ans=cache[pos][sum];
    if(ans!=-1)
        return ans;

    ans=dp(pos+1,sum)+dp(pos+1,sum+arr[pos]);
    return ans;
}
