const int md = 998244353;
int dp[3005][3005];

void solve(){
    int n,s;
    cin >> n >> s;
    vector<int>v(n+5);
    FOR(i,1,n+1)cin >> v[i];
    memset(dp,0,sizeof dp);
    dp[n+1][0] = 1;
    RFOR(i,n,0){
        FOR(j,0,3001){
            dp[i][j] = dp[i+1][j];
            if(j > v[i])dp[i][j] += dp[i+1][j-v[i]],dp[i][j] %= md;
            else if(j == v[i])dp[i][j] += n-i+1,dp[i][j] %= md;
        }
    }
    int ans = 0;
    FOR(i,1,n+1)if(v[i] <= s)ans += (i*dp[i+1][s-v[i]])%md,ans %= md;
    cout << ans << "\n";
}

signed main()   
{
    showoff;
    int T = 1;
    //cin >> T;
    FOR(t,1,T+1){
        solve();
    }
    return 0;
}
