    vector<vector<optional<T>> > v ;
    ovv(int i=0, int j=0, T val = 0) : v(i, vector<optional<T>>(j, val) ){}
    optional<T> &operator()(int i, int j) {        if (i < 0 || j < 0 || sz(v) <= i || sz(v[i]) <= j) {            emp.reset();return emp;        }        else { return v[i][j]; }    }
    //再帰ver 遅いと思う
