ll gcd(ll val, ll b) {
	if (val < 0) val *= -1;
	if (b < 0) b *= -1;
	if (val == 0) return b;
	if (b == 0) return val;
	if (val%b == 0) return b;
	else return gcd(b, val%b);
}




vll divisor(ll n) {
	// returns common divisors in O(sqrt(min(n,m)))
	vll res;
	for (ll i = 1; i*i <= n; i++) {
		if (n%i == 0) {
			res.push_back(i);
			res.push_back(n / i);
		}
		if (i * i == n)res.push_back(i);
	}
	sort(res.begin(), res.end());
	return res;
}

vll divisor(ll n, ll m) {
	// returns common divisors in O(sqrt(min(n,m)))
	if (n > m) swap(n, m);
	vll res;
	for (ll i = 1; i*i <= n; i++) {
		if (n%i == 0) {
			if (m%i == 0) res.push_back(i);
			if (m % (n / i) == 0) res.push_back(n / i);
		}
		if (i * i == n && m % i == 0) res.push_back(i);
	}
	sort(res.begin(), res.end());
	return res;
}

vpll prime_factorize(ll n) {
	// returns prime factorization of n in O(sprt(n))
	vector<pll> res;
	for (ll p = 2; p*p <= n; ++p) {
		if (n%p != 0)continue;
		ll num = 0;
		while (n%p == 0) { ++num; n /= p; }
		res.push_back({ p,num });
	}
	if (n != 1) res.push_back(make_pair(n, 1));
	return res;
}

ll eulers_phi(ll n) {
	// returns the number of coprime integers in O(sqrt(n) + n^(1.4/log log n)) [ the number of prime divisors <= O(log(n^(1.4/log log n) ) ] 
	ll res = 0;
	auto primes = prime_factorize(n);
	ll psize = primes.size();
	rep(bit, 1, 1LL << psize) {
		ll bitsize = popcnt(bit);
		ll arg = (bitsize % 2 ? 1 : -1);
		ll base = 1;
		rep(i, 0, primes.size()) {
			ll p = primes[i].first;
			if(bit &(1LL << i)) 
				base *= p;
		}
		res += arg * (n / base);
	}
	return n - res;
}









template<class T>
T solve_recurrence_relation(const vector<T>& a, const vector<T>& p, ll n) {
	// solve : a[n] = p[0] * a[n-k] + ... + p[k-1] * a[n-1] by calc coefficient (Kitamasa method)
	// a[n] = x[0] * a[0] + x[1] * a[1] + ... + x[k-1] * a[k]

	assert(a.size() == p.size());
	auto k = SZ(p);
	if (n < k) {
		return a[n];
	}
	auto increment = [&](vector<T>& x) {
		x.insert(x.begin(), 0);
		rep(i, 0, k) {
			x[i] += x.back() * p[i];
		}
		x.pop_back();
	};
	auto dbl = [&](vector<T>& x) {
		vector<T> res(k);
		auto x_i = x;
		vector<vector<T>> X(k); 
		X[0] = x_i;
		rep(i, 1, k) {
			increment(x_i);
			X[i] = x_i;
		}
		rep(i, 0, k) {
			rep(j, 0, k) {
				res[i] += x[j] * X[j][i];
			}
		}
		swap(res, x);
	};
	function<void(vector<T>&, ll)> rec = [&](vector<T>& x, ll n) {
		if (n == 0) {
			x.resize(k);
			x[0] = 1;
		}
		else if (n & 1) {
			rec(x, --n);
			increment(x);
		}
		else {
			n /= 2;
			rec(x, n);
			dbl(x);
		}
	};
	vector<T> x;
	rec(x, n);
	T res = 0;
	rep(i, 0, k) {
		res += x[i] * a[i];
	}
	return res;
};







template<class underlying_t = ll, ll max_dim = INF>
class SparsePolynomial
{
	using coeff_t = map<ll, underlying_t>;
	coeff_t coeff;
public:
	SparsePolynomial() : coeff() {}
	SparsePolynomial(int x) : coeff({ { 0, x } }) {}
	explicit SparsePolynomial(const coeff_t& coeff_) : coeff(coeff_) { }
	SparsePolynomial(initializer_list<pair<ll, underlying_t>> coeff_) {
		for (auto& it : coeff_) {
			coeff[it.first] = it.second;
		}
	}
	SparsePolynomial& operator<<=(ll d) {
		coeff_t res;
		for (auto it = coeff.rbegin(); it != coeff.rend(); ++it) {
			if (it->first + d <= max_dim) {
				res[it->first + d] = it->second;
			}
		}
		coeff = res;
		return *this;
	}
	friend SparsePolynomial operator<<(SparsePolynomial lhs, int rhs) {
		return lhs <<= rhs;
	}
	SparsePolynomial& operator*=(SparsePolynomial rhs) {
		// O(max(coeff.size() * (rhs.coeff.size())^2)
		coeff_t res;
		for(auto& i: coeff) {
			for(auto& j: rhs.coeff) {
				if (i.first + j.first <= max_dim)
					res[i.first + j.first] += i.second * j.second;
			}
		}
		coeff = res;
		return *this;
	}
	friend SparsePolynomial operator*(SparsePolynomial lhs, const SparsePolynomial& rhs) {
		return lhs *= rhs;
	}
	SparsePolynomial& operator+=(const SparsePolynomial& rhs) {
		for(auto& i: rhs.coeff) {
			coeff[i.first] += i.second;
		}
		return *this;
	}
	friend SparsePolynomial operator+(SparsePolynomial lhs, const SparsePolynomial& rhs) {
		return lhs += rhs;
	}
	bool operator==(const SparsePolynomial& rhs) const {
		return coeff == rhs.coeff;
	}
	underlying_t operator[](ll d) const {
		auto it = coeff.find(d);
		if (it != coeff.end()) {
			return it->second;
		}
		else {
			return 0;
		}
	}
};

template<class T = ll, ll max_dim = INF>
struct Polynomial {
	vector<T> a; // coefficients
	Polynomial() = default;
	Polynomial(const vector<T>& coeff) : a(coeff) {}
	Polynomial(ll c) : a{c} {}
	Polynomial(const vector<pair<ll, T>>& coeff) {
		//sort_by<0>(coeff);
		a.resize(coeff.back().first+1);
		rep(i, 0, coeff.size()) {
			a[coeff[i].first] = coeff[i].second;
		}
	}
	Polynomial& operator<<=(ll d) {
		auto n = a.size();
		a.resize(a.size() + d);
		rrep(i, 0, n) {
			a[i + d] = a[i];
		}
		rep(i, 0, d) {
			a[i] = 0;
		}
		return *this;
	}
	friend Polynomial operator<<(Polynomial lhs, int rhs) {
		return lhs <<= rhs;
	}
	Polynomial& operator>>=(ll d) {
		rep(i, 0, a.size() - d) {
			a[i] = a[i+d];
		}
		a.resize(a.size() - d);
		return *this;
	}
	friend Polynomial operator>>(Polynomial lhs, int rhs) {
		return lhs >>= rhs;
	}
	Polynomial& operator*=(Polynomial rhs) {
		auto res = vector<T>(min(SZ(a) + SZ(rhs.a)-1, max_dim+1));
		rep(i, 0, a.size()) {
			if (a[i] == 0)
				continue;
			rep(j, 0, rhs.a.size()) {
				if(i+j <= max_dim)
					res[i + j] += a[i] * rhs.a[j];
			}
		}
		a = res;
		return *this;
	}
	friend Polynomial operator*(Polynomial lhs, const Polynomial& rhs) {
		return lhs *= rhs;
	}
	Polynomial& operator+=(const Polynomial& rhs) {
		a.resize(max(a.size(), rhs.a.size()));
		rep(i, 0, rhs.a.size()) {
			a[i] += rhs.a[i];
		}
		return *this;
	}
	friend Polynomial operator+(Polynomial lhs, const Polynomial& rhs) {
		return lhs += rhs;
	}
	bool operator==(const Polynomial& rhs) const {
		return a == rhs.a;
	}
	function<T(ll)> div(const Polynomial& Q) const {
		// return generating function of rational function q(x)/p(x).
		// O((a.size())^2)

		auto q = a;
		auto p = Q.a;
		vector<T> tail;
		auto p0 = p[0];
		p.erase(p.begin());
		if (q.size() <= p.size()) {
			q.resize(p.size());
		}


		rep(i, 0, p.size()) {
			p[i] /= p0;
			p[i] *= -1;
		}
		rep(i, 0, q.size()) {
			q[i] /= p0;
		}
		auto& init = q;
		rep(i, 1, init.size()) {
			rep(j, 1, min(i,SZ(p))+1) {
				init[i] += p[j-1]* init[i-j];
			}
		}
		if (q.size() > p.size()) {
			tail.insert(tail.begin(), q.begin(), q.begin() + q.size() - p.size());
			q.erase(q.begin(), q.begin() + q.size() - p.size());
		}
		reverse(all(p));
		return [tail, init, p](ll n) {
			if (n < tail.size())
				return tail[n];
			else
				return solve_recurrence_relation(init, p, n - tail.size());
		};
	}
};






















