          right = dpR[j - a[i]];
        }

        dpA[j] += dpA[j - a[i]];
        dpA[j] %= mod;

        dpR[j] += dpR[j - a[i]];
        dpR[j] %= mod;
      }
    }
    if (a[i] == s) {
      upd = 1;
      right = dpR[0];
    }
    dpA[a[i]]++; dpA[a[i]] %= mod;
    dpR[a[i]] += (n - i); dpR[a[i]] %= mod;

    if (upd) {
      ll left = i + 1;
      ll add = (left * right) % mod;
      x += add; x %= mod;
    }
  }
  cout << x << "\n";
}

