    for (int i = 0; i < N; ++i) {
        for (int j = 0; j <= S; ++j) dp[i+1][j] += dp[i][j];
        if (A[i] <= S) dp[i+1][A[i]] += i+1;
        for (int j = 1; j <= S; ++j) if (A[i] + j <= S) dp[i+1][j+A[i]] += dp[i][j];

        if (A[i] == S) res += (i+1) * (N-i);
        for (int j = 1; j <= S; ++j) {
            if (A[i] + j == S) {
                res += dp[i][j] * (N - i);

                //cout << i << ", " << j << "; " << dp[i][j] << ",, " << dp[i][j] * (N - i) << endl;
            }
        }
    }

    for (int i = 0; i <= N; ++i) {
