            }
            else{
                dp[i-st][j]=adds(dp[i-1-st][j],(a[i]<=j ? dp[i-1-st][j-a[i]] : (ll)0));
            }
        }
    }
    for(int i=mid;i>=st;i--){
        for(int j=0;j<=S;j++){
            if(j==0){
                dp[i-st][j]=1; continue;
            }
            if(i==mid){
                if(a[i]==j) dp[i-st][j]=1;
                else dp[i-st][j]=0;
            }
            else{
                dp[i-st][j]=adds(dp[i+1-st][j],(a[i]<=j ? dp[i+1-st][j-a[i]] : (ll)0));
            }
        }
    }
    ll t1[s+1]={0};
    for(int j=0;j<=S;j++){
        for(int i=mid+1;i<=end;i++){
            t1[j]=adds(t1[j],dp[i-st][j]);
        }
    }
    for(int j=0;j<=S;j++){
        ll g=0;
        for(int i=mid;i>=st;i--){
            g=adds(g,dp[i-st][j]);
        }
        ans=adds(ans, (g*t1[s-j])%mod );
    }
    return ans;
}

