long long cnt(int idx, int cur) {
  if (cur == 0) return 1;
  if (cur < 0 || idx == n) return 0;
  if (dp2[idx][cur] != -1) {
    return dp2[idx][cur];
  }
  long long res1, res2;
  res1 = cnt(idx + 1, cur - a[idx]);
  res2 = cnt(idx + 1, cur);
  return dp2[idx][cur] = res1 + res2;
}

long long f(int idx, int cur) {
