{
    a = (a + mod) % mod;
    b = (b + mod) % mod;
    return (1ll * a * b) % mod;
}

int add(int a, int b)
{
    a = (a + mod) % mod;
    b = (b + mod) % mod;
    return (a + b) % mod;
}

int solve(int i , int sum)
{
    if (i==0) return sum == s;
    if (sum > s) return 0;

    if (sum == s) return i+1;

    if (dp[i][sum] != -1)
        return dp[i][sum];

    int ans = solve(i-1 , sum);
    ans = add(ans , solve(i-1 , sum+a[i]));

    return dp[i][sum] = ans;
}

