void solve() {
	const LL P = 998244353;
	int N, S;
	cin >> N >> S;
	vector<int> A(N);
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
	}
	/*
	dp[i][j]
	A_iまで見たときに
	合計がjになる場合の数。
	更新A_(i+1)で更新される
	dp[i+1][j] += dp[i][j] mod
	dp[i+1][j+A_(i+1)] += dp[i][j] mod
	*/
	vector<vector<LL>> dp(N+1, vector<LL>(S+1,0));
	dp[0][0] = 1;
	for (int i = 0; i < N; ++i) {
		//A[i]
		LL ter = A[i];
		dp[i + 1][0] = 1;
		if (ter == S) {
			dp[i + 1][ter] = ((i + 1) * (N - i)) % P;
		}
		else if (ter < S) {
			dp[i + 1][0 + ter] = (i + 1) % P;
		}

		for (int s = 1; s < S; ++s) {
			dp[i + 1][s] += dp[i][s];
			dp[i + 1][s] %= P;
			LL wa = s + A[i];
			if (wa == S) {
				LL res = (dp[i][s] * (N - i)) % P;
				dp[i + 1][wa] += res;
				dp[i + 1][wa] %= P;
			}
			else if(wa<S){
				dp[i + 1][wa] += dp[i][s];
				dp[i + 1][wa] %= P;
			}
		}
	}
	LL ans = 0;
	for (int i = 0; i <= N; ++i) {
		ans += dp[i][S];
		ans %= P;
	}
	cout << ans << endl;
}

