mint dp[3005][3005][3];

void solve() {
    int N, S; cin >> N >> S;
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    dp[0][0][0] = 1;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= S; j++) {
            // 左端未選択  (区間がまだはじまってない)
            dp[i+1][j][0] += dp[i][j][0];                           // 左端未選択
            if (j+A[i] <= S) {
                dp[i+1][j+A[i]][1] += dp[i][j][0] * (i+1);          // 左端として選択
                dp[i+1][j+A[i]][2] += dp[i][j][0] * (i+1) * (N-i);  // 左端かつ右端として選択
            }


            // 左端選択、右端未選択  (区間の途中)
            dp[i+1][j][1] += dp[i][j][1];                           // 未選択
            if (j+A[i] <= S) {
                dp[i+1][j+A[i]][1] += dp[i][j][1];                  // 選択
                dp[i+1][j+A[i]][2] += dp[i][j][1] * (N-i);          // 右端として選択
            }


            // 右端選択済み  (区間が選択済み)
            dp[i+1][j][2] += dp[i][j][2];                           // 未選択
        }
    }

    cout << dp[N][S][2] << '\n';
}

int main() {
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);

    solve();

    return 0;
}

