fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val s = sc.nextInt()
    val a = Array(n) { sc.nextInt() }
    val mod = 998244353L
    var dp = Array(s + 1) { Array(3) { 0L } }
    // dp[i][j] := 選んだ数の総和がiで、状態がjであるような場合の数
    // 状態0 : 左端を選んでいない
    // 状態1 : 左端を選んだけど右端を選んでいない
    // 状態2 : 右端も選んだ
    // 最初はdp[i][j][k]にしてたけどTLEするので、配列使いまわしによる高速化を試す。通ってほしい…。
    dp[0][0] = 1
    for (i in 0 until n) {
        val newdp = Array(s + 1) { Array(3) { 0L } }
        for (j in 0..s) {
            //まずはa[i]を加えない場合

            //状態0は常に一定
            newdp[j][0] = dp[j][0]

            //左端を新たに決める(状態0→1)または決めた左端を引き継ぐ(状態1→1)
            newdp[j][1] += dp[j][0] + dp[j][1]

            //左端・右端を同時に決める(状態0→2)、右端のみ新たに決める(状態1→2)、決めた右端を引き継ぐ(状態2→2)
            newdp[j][2] += dp[j][0] + dp[j][1] + dp[j][2]

            //a[i]を加える場合
            if (j + a[i] <= s) {
                //右端を決めてある場合a[i]を加えられない
                newdp[j + a[i]][1] += dp[j][0] + dp[j][1]
                newdp[j + a[i]][2] += dp[j][0] + dp[j][1]
            }
            newdp[j][1] %= mod
            newdp[j][2] %= mod
        }
        dp = newdp
    }
    println(dp[s][2])
}

