    public static long calc(int n, int target, int[] nums){
        long[][] dp = new long[n+1][target+1];
        long mod = 998244353;
        dp[0][0] = 1;
        for(int i=1; i<=n; i++){
            for(int k=0; k<=target; k++){
                dp[i][k] = (dp[i-1][k] + (k-nums[i-1]>=0 ? dp[i-1][k-nums[i-1]] : 0))%mod;
            }
        }
        return dp[n][target];
    }
}

