	public static long fun(int a[],int m,int n,int i,long c[],int t,long dp[][][]){
		if(n<0)
		return 0;

		if(dp[m][n][i]>0)
		return dp[m][n][i];

		if(m-a[n]==0){

			//c[0]+=((long)a.length-i)*((long)n+1);
			//c[0]%=998244353;
			dp[m][n][i]+=((long)a.length-i)*((long)n+1);
		}
		else if(m-a[n]>0){
			dp[m][n][i]+=fun(a, m-a[n], n-1, i, c, t,dp);
		}
		if(t==m)
		dp[m][n][i]+=fun(a, m, n-1, i-1, c,t,dp);
		else dp[m][n][i]+=fun(a, m, n-1, i, c, t,dp);
		return dp[m][n][i]%998244353;

	}

