  ModCalculator mc;

  Solver(int n, int s, int[] as) {
    this.n = n;
    this.s = s;
    this.as = as;
  }

  public long solve() {
    mc = new ModCalculator(998244353L);
    long[] dptable = new long[s + 1];

    if (as[0] <= s) {
      dptable[as[0]] = 1;
    }
    dptable[0] = 1;

    long answer = dptable[s];
    for (int i = 1; i < n; i++) {
      dptable[0] = mc.add(dptable[0], 1);
      for (int j = s - as[i]; j >= 0; j--) {
        dptable[j + as[i]] = mc.add(dptable[j + as[i]], dptable[j]);
      }
      answer = mc.add(answer, dptable[s]);
      /*
