    static class FKnapsackForAllSegments {
        private static final int MOD = (int) 1e9 + 7;

        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            // out.setCaseLabel(LightWriter.CaseLabel.NONE);
            int n = in.ints(), s = in.ints();
            long[][] a = new long[n][s + 1];
            for (int i = 0; i < n; i++) {
                a[i][0] = 1;
                int x = in.ints();
                if (x <= s) a[i][x] = 1;
            }
            SparseTable<long[]> table = new SparseTable<>(
                    a,
                    (x, y) -> {
                        long[] r = Arrays.copyOf(FFT.convolve(x, y), s + 1);
                        for (int i = 0; i <= s; i++) r[i] %= MOD;
                        return r;
                    }
            );
            long ans = 0;
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j <= n; j++) {
                    ans += table.query(i, j)[s];
                    ans %= MOD;
                }
            }
            out.ans(ans).ln();
        }

    }

