    void solve(){
        int N = in.nextInt(), S = in.nextInt();
        int[] A = in.nextIntArray1Index(N);

        long[][][] dp = new long[3][N+1][S+1];
        dp[0][0][0] = 1;
        for(int i = 0; i < N; i++){
            for(int j = 0; j <= S; j++){
                dp[0][i+1][j] = (dp[0][i+1][j] + dp[0][i][j]) % MOD;
                dp[1][i+1][j] = (dp[1][i+1][j] + (dp[0][i][j] + dp[1][i][j]) % MOD) % MOD;
                dp[2][i+1][j] = (dp[2][i+1][j] + (dp[0][i][j] + (dp[1][i][j] + dp[2][i][j]) % MOD) % MOD) % MOD;

                int J = j + A[i+1];
                if(J > S) continue;

                dp[1][i+1][J] = (dp[1][i+1][J] + (dp[0][i][j] + dp[1][i][j]) % MOD) % MOD;
                dp[2][i+1][J] = (dp[2][i+1][J] + (dp[0][i][j] + dp[1][i][j]) % MOD) % MOD;
            }
        }
        out.println(dp[2][N][S]);
