	@SuppressWarnings("static-method")
	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Beginner Contest 159 F問題
		 * 考察メモ
		 * dp[R][S]を左からRまで見て合計がSになるような場合の数とする
		 * dp[R][0]=Rとすると答えが出せて楽(！？)
		 *
		 * ところでModIntegerの二次元配列はTLE、悲しいね……
		 * intに書き直せば多分大丈夫なので投げます
		 */
		int N = io.nextInt(), S = io.nextInt();
		int[] A = io.nextInt(N);

		ModUtility mod = new ModUtility(new Prime(998_244_353));
		int[][] dp = new int[N + 1][S + 1];
		for (int i = 0;i < dp.length;++ i) dp[i][0] = i + 1;
		for (int i = 0;i < N;++ i) {
			for (int j = 1;j < A[i];++ j) dp[i + 1][j] = dp[i][j];
			for (int j = A[i];j <= S;++ j) dp[i + 1][j] = mod.add(dp[i][j], dp[i][j - A[i]]);
		}
		int ans = 0;
		for (int[] i : dp) ans = mod.add(ans, i[S]);
		io.println(ans);
	}

