	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Beginner Contest 159 F問題
		 * 考察メモ
		 * dp[R][S]を左からRまで見て合計がSになるような場合の数とする
		 * dp[R][0]=Rとすると答えが出せて楽(！？)
		 *
		 */
		int N = io.nextInt(), S = io.nextInt();
		int[] A = io.nextInt(N);

		ModUtility mod = new ModUtility(new Prime(998_244_353));
		ModInteger[][] dp = new ModInteger[N + 1][S + 1];
		for (int i = 0;i <= S;++ i) dp[0][i] = mod.create(0);
		for (int i = 0;i < dp.length;++ i) dp[i][0] = mod.create(i + 1);
		for (int i = 0;i < N;++ i) {
			for (int j = 1;j < A[i];++ j) dp[i + 1][j] = mod.create().addEqual(dp[i][j]);
			for (int j = A[i];j <= S;++ j) dp[i + 1][j] = dp[i][j].add(dp[i][j - A[i]]);
		}
		ModInteger ans = mod.create();
		for (int i = 0;i < dp.length;++ i) ans.addEqual(dp[i][S]);
		io.println(ans);
	}

