    long[][] dp = new long[2][S + 1]; // dp[pre,cur][S]:= f(L,R) when A_i is used or not.
    for (int i = 0; i < N; i++) {
      // Case when A[i] is not used. This is a seed scaffold.
      dp[0][0] += 1;
