    long sum(int[] a, int L, int R, int S){
        if(L == R)return a[L] == S?((L+1)*((long)a.length-R))%MOD:0;
        int mid = (L+R)/2;
        long ans = 0;
        int le = mid-L+1, ri = R-mid;
        for(int i = 0; i<= le; i++)Arrays.fill(ldp[i] ,0);
        for(int i = 0; i<= ri; i++)Arrays.fill(rdp[i] ,0);
        Arrays.fill(lf, 0);Arrays.fill(rf, 0);
        rdp[0][0] = 1;
        ldp[0][0] = 1;
        for(int i = 1, pos = mid+1; i<= ri; i++, pos++){
            for(int sum = 0; sum <= S; sum++){
                rdp[i][sum] = (rdp[i-1][sum]+(sum >= a[pos]?rdp[i-1][sum-a[pos]]:0));
                if(rdp[i][sum] >= MOD)rdp[i][sum] -= MOD;
                rf[sum] += (a.length-pos)*(rdp[i][sum]+MOD-rdp[i-1][sum])%MOD;
                if(rf[sum] >= MOD)rf[sum] -= MOD;
            }
        }
        for(int i = 1, pos = mid; i <= le; i++, pos--){
            for(int sum = 0; sum <= S; sum++){
                ldp[i][sum] = (ldp[i-1][sum]+(sum >= a[pos]?ldp[i-1][sum-a[pos]]:0));
                if(ldp[i][sum] >= MOD)ldp[i][sum] -= MOD;
                lf[sum] += ((pos+1)*(ldp[i][sum]-ldp[i-1][sum]+MOD))%MOD;
                if(lf[sum] >= MOD)lf[sum] -= MOD;
            }
        }
        for(int i = 1; i< S; i++){ans += (lf[i]*rf[S-i]%MOD);if(ans >= MOD)ans -= MOD;}
        ans += sum(a, L, mid, S)+sum(a, mid+1, R, S);
        while(ans >= MOD)ans -= MOD;
        return ans;
    }
