                dp[i + 1][j][2] = (dp[i + 1][j][2] + dp[i][j][0] + dp[i][j][1] + dp[i][j][2]) % MOD;
                if (j + a[i] <= s) {
                    dp[i + 1][j + a[i]][1] = (dp[i][j][0] + dp[i][j][1]) % MOD;
                    dp[i + 1][j + a[i]][2] = (dp[i][j][0] + dp[i][j][1]) % MOD;
                }
            }
        }

        System.out.println(dp[n][s][2]);
    }
}

