    static long mod = 998244353;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int s = in.nextInt();
        int[] a = in.nextIntArray(n);
        long ans = 0;
        long[][] dp = new long[n + 1][s + 1];
        for (int i = 1; i <= n; i++) {
            dp[i - 1][0]++;
            for (int j = 1; j <= s; j++) {
                if (j - a[i - 1] >= 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - a[i - 1]]) % mod;
                }
                dp[i][j - 1] = (dp[i][j - 1] + dp[i - 1][j - 1]) % mod;
            }
            ans += (n - i + 1) * dp[i][s] % mod;
        }
        out.println(ans % mod);
    }

