        long ans = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = s; j > 0; j--) {
                if (j >= a[i]) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - a[i]]) % mod;
                    if (j == a[i]) {
                        dp[i][j] = (dp[i][j] + i) % mod;
