@SuppressWarnings("unused")
public class Main {
    FastScanner in;
    PrintWriter out;
    final static int MOD = 998244353;//(int)1e9+7;
    final static long INF = Long.MAX_VALUE / 2;

    void solve(){
        int N = in.nextInt(), S = in.nextInt();
        int[] A = in.nextIntArray1Index(N);

        int[][][] dp = new int[N+1][S+1][3];
        dp[0][0][0] = 1;
        for(int i = 0; i < N; i++){
            for(int j = 0; j <= S; j++){
                dp[i+1][j][0] = (dp[i+1][j][0] + dp[i][j][0]) % MOD;
                dp[i+1][j][1] = (dp[i+1][j][1] + dp[i][j][0]) % MOD;
                dp[i+1][j][2] = (dp[i+1][j][2] + dp[i][j][0]) % MOD;

                dp[i+1][j][1] = (dp[i+1][j][1] + dp[i][j][1]) % MOD;
                dp[i+1][j][2] = (dp[i+1][j][2] + dp[i][j][1]) % MOD;

                dp[i+1][j][2] = (dp[i+1][j][2] + dp[i][j][2]) % MOD;

                int J = j + A[i+1];
                if(J > S) continue;

                dp[i+1][J][1] = (dp[i+1][J][1] + dp[i][j][0]) % MOD;
                dp[i+1][J][2] = (dp[i+1][J][2] + dp[i][j][0]) % MOD;

                dp[i+1][J][1] = (dp[i+1][J][1] + dp[i][j][1]) % MOD;
                dp[i+1][J][2] = (dp[i+1][J][2] + dp[i][j][1]) % MOD;
            }
        }
        out.println(dp[N][S][2]);
    }

