    static int N, S;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        S = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static int solve() {
        // 開始位置覚えてないとダメじゃんってなって終了したけど最初からかけておけばよいのね…
        int[] curr = new int[S+1];
        int ret = 0;
        for (int i = 0; i < N; i++) {
            int a = A[i];
            int[] next = new int[S+1];
            // 開始を決める
            // 横に(i+1)個数あるので掛けておくと開始位置を覚えておかないで済む(これが出なかった...)
            if( a <= S ) {
                next[a] += i+1;
            }

            // 足したり足さなかったり
            for (int s = 0; s < S; s++) {
                if( s + a <= S ) {
                    next[s+a] += curr[s];
                    next[s+a] %= MOD;
                }
                next[s] += curr[s];
                next[s] %= MOD;
            }

            // ここで終了した分
            int end = next[S] * (N-i) % MOD;
            ret += end;
            ret %= MOD;
            curr = next;
        }
        return ret;
    }

    static int MOD = 998244353;

