        ldp[0][0] = 1;
        for(int i = 1, pos = mid+1; i<= ri; i++, pos++){
            for(int sum = 0; sum <= S; sum++){
                rdp[i][sum] = (rdp[i-1][sum]+(sum >= a[pos]?rdp[i-1][sum-a[pos]]:0));
                if(rdp[i][sum] >= MOD)rdp[i][sum] -= MOD;
//                rf[sum] += (a.length-pos)*(rdp[i][sum]+MOD-rdp[i-1][sum])%MOD;
