        for(int sum = 0; sum <= S; sum++) {
            long tot = 0, tot2 = 0;
            for (int i = 1, pos = mid; i <= le; i++, pos--) {
                tot += ((pos+1)*(ldp[i][sum]-ldp[i-1][sum]+MOD))%MOD;
                if(tot >= MOD)tot -= MOD;
