        int[] arr = new int[MAXN];
        long[][] dp = new long[3005][3005];

        long go(int ind, int sum) {
            if (sum > s)
                return 0;
            if (sum == s)
                return n - ind + 1;
            if (ind == n)
                return 0;
            if (dp[ind][sum] != -1)
                return dp[ind][sum];
            long subarrays = go(ind + 1, sum);
            subarrays += go(ind + 1, sum + arr[ind]);
            subarrays %= mod;
            dp[ind][sum] = subarrays;
            return subarrays;
        }

