        dp0[0][0] = 1;
        for(int i = 0; i < N; i++){
            for(int j = 0; j <= S; j++){
                dp0[i+1][j] = (dp0[i+1][j] + dp0[i][j]) % MOD;
                dp1[i+1][j] = (dp1[i+1][j] + (dp0[i][j] + dp1[i][j]) % MOD) % MOD;
                dp2[i+1][j] = (dp2[i+1][j] + (dp0[i][j] + (dp1[i][j] + dp2[i][j]) % MOD) % MOD) % MOD;

