        // condition: L <= i1 < i2 < i3 ... < ik <= i such that Ai1 + Ai2 +
        // ... + Aik = S.
        // The answer is sum(dp[i][S] for i in [0:n])
        int[][] dp = new int[n + 1][s + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            int x = A[i - 1];
            for (int j = 0; j <= s; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j == x) {
                    // start a new sequence
                    dp[i][j] = (dp[i][j] + i) % MOD;
                }
                else if (j > x) {
                    // continue a sequence 
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - x]) % MOD;
                }
            }
            ans = (ans + dp[i][s]) % MOD;
        }
        out.println(ans);
    }

    private int gcd(int a, int b) {
        while (true) {
            if (b == 0) return a;
            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long powm(long x, long p) {
        long res = 1;
        while (p > 0) {
            if (p % 2 == 1)
                res = res * x % MOD;
            x = x * x % MOD;
            p /= 2;
        }
        return res;
    }


