		a = new long[n];
		for (int i = 0; i < n; i++)
			a[i] = sc.nextLong();
		memo = new long[n][s + 1][3];
		for (long[][] u : memo)
			for (long[] j : u)
				Arrays.fill(j, -1);
		System.out.println(dp(0, s, 0));
		out.close();
