            for(int j = 0; j <= S; j++){
                dp[i+1][j][0] = add(dp[i+1][j][0], dp[i][j][0]);
                dp[i+1][j][1] = add(dp[i+1][j][1], dp[i][j][0] + dp[i][j][1]);
                dp[i+1][j][2] = add(dp[i+1][j][2], dp[i][j][0] + dp[i][j][1] + dp[i][j][2]);

                int J = j + A[i+1];
                if(J > S) continue;

                dp[i+1][J][1] = add(dp[i+1][J][1], dp[i][j][0] + dp[i][j][1]);
                dp[i+1][J][2] = add(dp[i+1][J][2], dp[i][j][0] + dp[i][j][1]);
