                var dp = new long[N + 1, S + 1];
                dp[0, 0] = 1;
                for(int n = 0; n < N; ++n)
                {
                    var a = A[n];
                    for(int s = S; s >= 0; --s)
                    {
                        dp[n + 1, s] = (dp[n, s] + (s >= a ? dp[n, s - a] : 0)) % P;
                    }
                }
                long sum = 0;
                for(int l = 0; l <= N; ++l)
                {
                    for (int r = l; r <= N; ++r)
                    {
                        sum = (sum + (((dp[r, S] - dp[Math.Max(0,l-1), S]) * (l + 1)) % P) * (N - r + 1)) % P;
                    }
                }
                Console.WriteLine(sum);
            }
