		{
			var cin = new Scanner2();
			int n = cin.Int();
			int s = cin.Int();
			var a = cin.ArrayInt(n);

			long P = 998244353;

			var dp = new long[s + 1];
			for (int i = 0; i < n; i++) {
				var dst = new long[s + 1];

				for (int j = 0; j <= s; j++) {
					if (dp[j] == 0) {
						continue;
					}

					if (j + a[i] <= s) {
						dst[j + a[i]] += (dp[j] * (j + a[i] == s ? (n - i) : 1)) % P;
						dst[j + a[i]] %= P;
					}

					dst[j] += dp[j];
				}

				if (a[i] <= s) {
					dst[a[i]] += ((1 + i) * (a[i] == s ? (n - i) : 1)) % P;
					dst[a[i]] %= P;
				}
				dp = dst;
			}

			var ans = dp[s];
			Console.WriteLine(ans);
		}
	}

	public struct ModInt
	{
		public static long P { get; set; } = (long)1e9 + 7;

		public static ModInt Pow(ModInt value, long k)
		{
			return Pow(value.Value, k);
		}

		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		public static ModInt Inverse(ModInt value)
		{
			return Pow(value, P - 2);
		}

		public long Value;

		public ModInt(long value)
		{
			value %= P;
			if (value < 0) {
				value += P;
			}

			Value = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.Value += rhs.Value;
			if (lhs.Value >= P) {
				lhs.Value -= P;
			}
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.Value -= rhs.Value;
			if (lhs.Value < 0) {
				lhs.Value += P;
			}

			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			return new ModInt(lhs.Value * rhs.Value % P);
		}
		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n)
		{
			n %= P;
			if (n < 0) {
				n += P;
			}

			return new ModInt(n);
		}

		public override string ToString()
		{
			return Value.ToString();
		}
	}

