			long P = 998244353;

			var dp = new long[s + 1];
			for (int i = 0; i < n; i++) {
				var dst = new long[s + 1];

				for (int j = 0; j <= s; j++) {
					if (dp[j] == 0) {
						continue;
					}

					if (j + a[i] == s) {
						dst[j + a[i]] = (dst[j + a[i]]  + dp[j] * (n - i)) % P;
					} else if (j + a[i] < s) {
						dst[j + a[i]] = (dst[j + a[i]] + dp[j]) % P;
					}

					dst[j] = (dst[j] + dp[j]) % P;
				}

				if (a[i] == s) {
					dst[a[i]] = (dst[a[i]] + (1 + i) * (n - i)) % P;
				} else if (a[i] <= s) {
					dst[a[i]] = (dst[a[i]] + (1 + i)) % P;
				}
				dp = dst;
			}

