namespace Kujikatsu036.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc159/tasks/abc159_f
    /// </summary>
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            Modular.Mod = 998244353;
            var (itemCount, sum) = inputStream.ReadValue<int, int>();
            var values = inputStream.ReadIntArray();

            const int NotStarted = 0;
            const int Started = 1;

            var results = new Modular[itemCount + 1, sum + 1, Started + 1];

            var result = Modular.Zero;
            results[0, 0, NotStarted] = 1;
            for (int item = 0; item < itemCount; item++)
            {
                for (int s = 0; s <= sum; s++)
                {
                    // 選ばない
                    results[item + 1, s, NotStarted] += results[item, s, NotStarted];   // 始めない
                    results[item + 1, s, Started] += results[item, s, NotStarted];      // 始めたけどスルー
                    results[item + 1, s, Started] += results[item, s, Started];         // 始まってるけどスルー

                    // 選ぶ
                    var next = s + values[item];
                    if (next <= sum)
                    {
                        results[item + 1, next, Started] += results[item, s, NotStarted];   // 始める
                        results[item + 1, next, Started] += results[item, s, Started];      // 続ける
                    }
                }

                result += results[item + 1, sum, Started];
            }

            yield return result;
        }
    }
}

