public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		long S = GetLong();
		var A = GetLongs(N);

		var dp = new MInt[N + 1, S + 1, 3];
		dp[0, 0, 0] = new MInt(1);
		for(long i = 0; i < N; i++)
		{
			for(long j = 0; j <= S; j++)
			{
				dp[i + 1, j, 0] += dp[i, j, 0];
				dp[i + 1, j, 1] += dp[i, j, 0];
				dp[i + 1, j, 2] += dp[i, j, 0];
				if(j + A[i] <= S)
				{
					dp[i + 1, j + A[i], 1] += dp[i, j, 0];
					dp[i + 1, j + A[i], 2] += dp[i, j, 0];
				}

				dp[i + 1, j, 1] += dp[i, j, 1];
				dp[i + 1, j, 2] += dp[i, j, 1];
				if(j + A[i] <= S)
				{
					dp[i + 1, j + A[i], 1] += dp[i, j, 1];
					dp[i + 1, j + A[i], 2] += dp[i, j, 1];
				}

				dp[i + 1, j, 2] += dp[i, j, 2];
			}
		}
		WriteLine(dp[N, S, 2].Val);
	}
}

public struct MInt
{
	private const long MOD = 998244353;
	private static MInt[] f = null;
	private static MInt[] g = null;
	public long Val { get; private set; }

	public MInt(long v)
	{
		Val = (v + MOD) % MOD;
	}

	public static void InitTable(int N) => InitTable((long)N);
	public static void InitTable(long N)
	{
		f = new MInt[N + 1];
		f[0] = new MInt(1);
		for(long i = 1; i <= N; i++)
			f[i] = f[i - 1] * i;

		g = new MInt[N + 1];
		g[N] = MPow(f[N], MOD - 2);
		for(long i = N; i > 0; i--)
			g[i - 1] = g[i] * i;
	}

	public static MInt MComb(long n, long k)
	{
		if(n < 0 || n < k)
			return new MInt(0);

		return f[n] * g[k] * g[n - k];
	}

	public static MInt operator+(MInt x, long y) => x + new MInt(y);	
	public static MInt operator+(long x, MInt y) => new MInt(x) + y;
	public static MInt operator+(MInt x, MInt y)
	{
		long tmp = x.Val + y.Val;
		if(tmp >= MOD)
			tmp -= MOD;
		return new MInt(tmp);
	}

	public static MInt operator-(MInt x, long y) => x - new MInt(y);
	public static MInt operator-(long x, MInt y) => new MInt(x) - y;
	public static MInt operator-(MInt x, MInt y)
	{
		long tmp = x.Val;
		if(tmp < y.Val)
			tmp += MOD;
		tmp -= y.Val;
		return new MInt(tmp);
	}

	public static MInt operator*(MInt x, MInt y) => new MInt((x.Val * y.Val) % MOD);
	public static MInt operator*(MInt x, long y) => x * new MInt(y);
	public static MInt operator*(long x, MInt y) => new MInt(x) * y;

	public static MInt operator/(MInt x, MInt y) => x * MPow(y, MOD - 2);
	public static MInt operator/(MInt x, long y) => x * MPow(y, MOD - 2);
	public static MInt operator/(long x, MInt y) => x * MPow(y, MOD - 2);

	public static MInt MPow(MInt x, MInt y) => MPow(x.Val, y.Val);
	public static MInt MPow(MInt x, long y) => MPow(x.Val, y);
	public static MInt MPow(long x, MInt y) => MPow(x, y.Val);
	public static MInt MPow(long x, long y)
	{
		long exp = y;
		long xx = x;
		long res = 1;
		while(exp > 0)
		{
			if((exp & 1) == 1)
				res = (res * xx) % MOD;

			xx = (xx * xx) % MOD;
			exp >>= 1;
		}
		return new MInt(res);
	}
}

