        public static int funct(int l, int r, int[] a, int s)
        {
            int bit_num = r - l + 1;
            int condition_num = (int)Math.Pow(2, bit_num);
            int[] conds = new int[condition_num];
            int sum = 0;
            for(int i = 0; i < conds.Length; i++)
            {
                bool[] digits = Convert.ToString(i, 2).Select(c => c=='1').ToArray();
                for(int j = 1; j<bit_num; j--)
                {
                    if(digits[digits.Length - j])
                    {
                        sum += a[j - 1];
                    }
                }
            }
            return sum;



