            long mod = 998244353;

            long[,] dp = new long[3030, 6060];
            long ans = 0;
            for (int i = 0; i < N; i++)
            {
                dp[i + 1, A[i]] += dp[i + 1, A[i]] + i + 1;
                dp[i + 1, A[i]] %= mod;
                for (int j = 0; j <= S; j++)
                {
                    dp[i + 1, j] = (dp[i + 1, j] + dp[i, j]) % mod;
                    if (j + A[i] <= S)
                    {
                        dp[i + 1, j + A[i]] = (dp[i + 1, j + A[i]] + dp[i, j]) % mod;
                    }
                }
            }

            Draw2D(dp);

            for (int i = 0; i <= N; i++)
            {
                ans += dp[i, S];
                ans %= mod;
            }

            Console.WriteLine(ans);
