namespace Kujikatsu036.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc159/tasks/abc159_f
    /// </summary>
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            Modular.Mod = 998244353;
            var (itemCount, sum) = inputStream.ReadValue<int, int>();
            var values = inputStream.ReadIntArray();

            const int None = 0;
            const int L = 1;
            const int LR = 2;

            var results = new Modular[itemCount + 1, sum + 1, LR + 1];

            results[0, 0, None] = 1;
            for (int item = 0; item < itemCount; item++)
            {
                for (int s = 0; s <= sum; s++)
                {
                    // 選ばない
                    results[item + 1, s, None] += results[item, s, None];   // 始めない
                    results[item + 1, s, L] += results[item, s, None];      // 始めたけどスルー
                    results[item + 1, s, L] += results[item, s, L];         // 始まってるけどスルー
                    results[item + 1, s, LR] += results[item, s, None];     // 始めて即終了
                    results[item + 1, s, LR] += results[item, s, L];        // 終わらせる
                    results[item + 1, s, LR] += results[item, s, LR];       // 終わってる

                    // 選ぶ
                    var next = s + values[item];
                    if (next <= sum)
                    {
                        results[item + 1, next, L] += results[item, s, None];   // 始める
                        results[item + 1, next, L] += results[item, s, L];      // 続ける
                        results[item + 1, next, LR] += results[item, s, None];  // 始めて即終了
                        results[item + 1, next, LR] += results[item, s, L];     // 終わらせる
                    }
                }
            }

            yield return results[itemCount, sum, LR];
        }
    }
}

