using System;
using System.Collections.Generic;
using System.Linq;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private int N, S;
    private int[] A;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = sc.NextInt();
        A = sc.IntArray();

        ModInt ans = 0;

        ModInt[] p = new ModInt[S + 1];
        p[0] = 1;
        for (int i = 0; i < N; i++)
        {
            for (int j = S; j >= 0; j--)
            {
                if(j + A[i] > S) continue;
                ModInt b = 1;
                if (j == 0) b *= i + 1;
                if (j + A[i] == S) b *= N - i;

                p[j + A[i]] += p[j] * b;
            }
        }

        Console.WriteLine(p[S]);
    }

    public static void Main(string[] args) => new Program().Solve();
}

