    public void Run() {
        var n = ni();
        var s = ni();
        var a = ni(n);
        int mod = ModInt.SetModValue(998244353);

        var memo = new long?[n + 1, s + 1, 3];

        Func<int, int, int, long> dfs = null;
        dfs = (pos, sum, t) => {
            if (sum < 0) return 0;
            if (pos == n) {
                return t == 2 && sum == 0 ? 1 : 0;
            }
            if (!memo[pos, sum, t].HasValue) {
                long val = 0;
                var x = a[pos];
                if (t == 0) {
                    val += dfs(pos + 1, sum, 0);
                    val += dfs(pos + 1, sum, 1);
                    val += dfs(pos + 1, sum, 2);
                    val += dfs(pos + 1, sum - x, 1);
