                } else if (t == 1) {
                    val += dfs(pos + 1, sum, 1);
                    val += dfs(pos + 1, sum, 2);
                    val += dfs(pos + 1, sum - x, 1);
                    val += dfs(pos + 1, sum - x, 2);
                } else { // 2
                    val += dfs(pos + 1, sum, 2);
                }

                memo[pos, sum, t] = val % mod;
            }
            return memo[pos, sum, t].Value;
        };

