        public static int funct(int l, int r, int[] a, int s)
        {
            int bit_num = r - l + 1;
            int condition_num = (int)Math.Pow(2, bit_num);
            int count = 0;
            for(int i = 0; i < condition_num; i++)
            {
                int sum = 0;
                String twodig = Convert.ToString(i, 2).PadLeft(bit_num, '0');
                bool[] digits = twodig.Select(c => c=='1').ToArray();
                for(int j = 1; j<=bit_num; j++)
                {
                    if(digits[digits.Length - j])
                    {
                        sum += a[l - 1 + j - 1];
                    }
                }
                if(sum == s)
                {
                    // Console.WriteLine("f(" + l + ", " + r + ") :" + twodig);
                    count++;
                }
            }
            return count;



        }
