    public object Calc()
    {
        var N = cr.Int;
        var S = cr.Int;
        var arr = cr.Split.Int;
        var dp = NewArray(N + 1, S + 1, (Mod)0);

        dp[0][0] = 1;
        for (int i = 0; i <= N; i++)
            dp[i][0] = i + 1;

        for (int i = 0; i < N; i++)
        {
            for (int j = 1; j < Math.Min(arr[i], S); j++)
                dp[i + 1][j] = dp[i][j];
            for (int j = arr[i]; j <= S; j++)
                dp[i + 1][j] = dp[i][j] + dp[i][j - arr[i]];
        }

        return dp.Select(ms => ms[S]).Aggregate((m1, m2) => m1 + m2);
    }
