    class ProgramE
    {
        public void main()
        {

            //入力
            string[] input = Console.ReadLine().Split(' ');
            int h = int.Parse(input[0]);
            int w = int.Parse(input[1]);
            int k = int.Parse(input[2]);


            //チョコの場所と白の位置把握
            int[,] choco = new int[h, w];
            int count = 0;

            for (int i = 0; i < h; i++)
            {
                string input2 = Console.ReadLine();
                for (int j = 0; j < w; j++)
                {
                    choco[i, j] = input2[j] - '0';
                    if (choco[i, j] == 1)
                        count++;
                }

            }

            //白がk個以下なら切る必要はない
            if (count <= k)
            {
                Console.WriteLine("0");
                return;
            }

            //切る回数
            int ans = 1000000;
            int sum = 0;


            //縦の切り口を決める
            for (int i = 0; i < (1 << (h - 1)); i++)
            {
                sum = 0;
                int[] comb = new int[h];
                //まずは横の切り口を記録
                for (int j = 0; j < h - 1; j++)
                    sum += (i >> j) & 1;//切る数を足す

                if (ans <= sum)
                    continue;

                //貪欲法で縦の切る回数を数える
                for (int j = 0; j < w; j++)
                {
                    int part = 0;
                    int flag = 0;
                    //それぞれの部分で分けながらカウントしていく
                    for (int l = 0; l < h; l++)
                    {
                        comb[part] += choco[l, j];

                        if (comb[part] > k)
                        {
                            if (j != 0)
                                flag = 1;
                            else
                                flag = 2;
                        }

                        part += (i >> l) & 1;

                    }

                    //もしk超えてしまったら出す(j !=0の処理）
                    if (flag == 1)
                    {

                        part = 0;
                        //リセット
                        for (int l = 0; l < h; l++)
                            comb[l] = 0;
                        //その列だけ再構成
                        for (int l = 0; l < h; l++)
                        {
                            comb[part] += choco[l, j];
                            part += (i >> l) & 1;
                        }

                        //条件を満たさないなら省く
                        for(int l = 0;l <= part;l++)
                        {
                            if (comb[l] > k)
                                sum += 1000000;
                        }


                        sum++;

                    }

                    //最初の時点で満たさない場合の処理
                    if(flag == 2)
                    {
                        sum = 1000000;
                        break;
                    }
                }

                //最小更新
                if (ans > sum)
                    ans = sum;

            }


            Console.WriteLine(ans);

        }
    }


