            dp[0, 0, 0] = 1;

            //i番目まで見てその和はSである。そしてそのときL、Rが決まっているかどうかで判定する（t=0は両方決まっていない、t=1はLのみ、t=2は確定）
            for (int i = 0; i < n; i++)
