                        dp[i + 1, temp, 2] += dp[i, j, 0] + dp[i, j, 1];
                        dp[i + 1, temp, 2] %= MOD;
                    }

                    //和が変わらないときの推移
                    dp[i + 1, j, 0] += dp[i, j, 0];//決まってない場合は普通に足す
                    dp[i + 1, j, 0] %= MOD;
                    dp[i + 1, j, 1] += dp[i, j, 0] + dp[i, j, 1];//iをLとしてきめる、前のときはすでにiより前でLが決まっているとき
                    dp[i + 1, j, 1] %= MOD;
                    dp[i + 1, j, 2] += dp[i, j, 0] + dp[i, j, 1] + dp[i, j, 2];//両方決まってない場合はiがL,Rのとき、Lが決まっていれば、
                    dp[i + 1, j, 2] %= MOD;
