    var t = a[i], l = i+1, r = n-i;
    if(t === s)ans += mul(l,r);
    if(t >= s)continue;
    ans += mul(dp[s-t],r);
    for(var j = s-t; --j;){
      dp[j+t] += dp[j];
      dp[j+t] %= mod;
    }
    dp[t] += l;
    dp[t] %= mod;
  }
  return ans % mod;
}

