    if S < a { continue }
    DP[i + 1][0]++
    ans += DP[i + 1][S - a] * (N - i) % p
    ans %= p
    for j := S - a; 0 <= j; j-- {
      DP[i + 1][j + a] += DP[i + 1][j]
    }
  }
  Write(ans)
}

