    result = ModInt(1)
    var N = n
    var M = m
    while M > 0:
      if (M and 1) == 1:
        result = result * N
      N = N * N
      M = M shr 1

  proc pow*(n: int, m: int): ModInt {.inline.} =
    pow(toModInt(n), m)

