def array(*args, initial=0):
    pre = "["*len(args)
    post = ""
    for a in args[::-1]:
        post += " for _ in range("+str(a)+")]"
    S = pre + str(initial) + post
    return eval(S)


def solve(N: int, S: int, A: "List[int]"):
    dp = array(S+1, 3, initial=0)
    dp[0][0] = 1
    for i in range(N):
        dp_past = copy.deepcopy(dp)
        # t=0軸
        for s in range(S+1):
            # A[i]を使う
            if s-A[i] >= 0:
                dp[s][0] += dp_past[s-A[i]][0]
                dp[s][0] %= MOD

        # t=1軸
        for s in range(S+1):
            if s-A[i] >= 0:
                dp[s][1] += dp_past[s-A[i]][1]
                dp[s][1] %= MOD
        if A[i] <= S:
            dp[A[i]][1] += i+1
            dp[s][1] %= MOD

        # t=2軸
        for s in range(S+1):
            if s-A[i] >= 0:
                dp[s][2] += (dp[s][1]-dp_past[s][1]) * (N-i)
                dp[s][2] %= MOD

    print(dp[S][2])

    return


