def array(*args, initial=0):
    pre = "["*len(args)
    post = ""
    for a in args[::-1]:
        post += " for _ in range("+str(a)+")]"
    S = pre + str(initial) + post
    return eval(S)


def solve(N: int, S: int, A: "List[int]"):
    dp = array(N+1, S+1, 3, initial=0)
    dp[0][0][0] = 1
    for i in range(N):
        # t=0軸
        for s in range(S+1):
            # A[i]を使わない
            dp[i+1][s][0] = dp[i][s][0]
            # A[i]を使う
            if s-A[i] >= 0:
                dp[i+1][s][0] += dp[i][s-A[i]][0]
                dp[i+1][s][0] %= MOD

        # t=1軸
        for s in range(S+1):
            dp[i+1][s][1] = dp[i][s][1]
            if s-A[i] >= 0:
                dp[i+1][s][1] += dp[i][s-A[i]][1]
                dp[i+1][s][1] %= MOD
        if A[i] <= S:
            dp[i+1][A[i]][1] += i+1
            dp[i+1][s][1] %= MOD

