fn solve() {
    input! {
        n: usize, s: usize,
        av: [usize; n]
    };

    let mut res = ModInt::zero();
    let mut dp = vec![vec![ModInt::zero(); s + 1]; n + 1];
    for i in 0..n {
        let a = av[i];
        dp[i][0] += ModInt::one();
        for j in 0..s + 1 {
            let c = dp[i][j];
            dp[i + 1][j] += c;
            if j + a > s {
                continue;
            }
            dp[i + 1][j + a] += c;
        }
        res += dp[i + 1][s];
    }
    println!("{}", res);
}

