  use std::ops::{Add, AddAssign, Div, DivAssign, Mul, MulAssign, Sub, SubAssign};

  pub trait Constant<T> {
    fn get() -> T;
  }

  pub struct ModU32<Mod> {
    _phantom: PhantomData<fn() -> Mod>,
    repr: u32,
