      self.repr.eq(&other.repr)
    }
  }

  impl<Mod: Constant<u32>> Eq for ModU32<Mod> {}

  impl<Mod: Constant<u32>> Default for ModU32<Mod> {
    fn default() -> Self {
      ModU32::from_repr(u32::default())
    }
  }

  impl<Mod: Constant<u32>> Hash for ModU32<Mod> {
    fn hash<H>(&self, state: &mut H)
    where
      H: Hasher,
    {
      self.repr.hash(state);
    }
  }

  impl<Mod: Constant<u32>> Debug for ModU32<Mod> {
    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
      Debug::fmt(&self.repr, f)
    }
  }

  impl<Mod: Constant<u32>> Display for ModU32<Mod> {
    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
      Display::fmt(&self.repr, f)
    }
  }

  impl<Mod: Constant<u32>> ModU32<Mod> {
    pub fn new(value: u32) -> Self {
      Self::from_repr(value % Mod::get())
    }

    fn from_repr(repr: u32) -> Self {
      debug_assert!(repr < Mod::get());
      ModU32 {
        _phantom: PhantomData,
        repr: repr,
      }
    }

    pub fn repr(self) -> u32 {
      self.repr
    }

    pub fn inverse(self) -> Self {
      let mut a = self.repr as i64;
      let mut b = Mod::get() as i64;
      let mut u = 1i64;
      let mut v = 0i64;
      while b != 0 {
        let t = a / b;
        a -= t * b;
        ::std::mem::swap(&mut a, &mut b);
        u -= t * v;
        ::std::mem::swap(&mut u, &mut v);
      }
      u %= Mod::get() as i64;
      if u < 0 {
        u += Mod::get() as i64;
      }
      Self::from_repr(u as u32)
    }

    pub fn pow(mut self, mut n: u32) -> Self {
      let mut acc = ModU32::from_repr(1);
      while n > 0 {
        if n % 2 == 1 {
          acc *= self;
        }
        self *= self;
        n /= 2;
      }
      acc
    }
  }

  impl<Mod: Constant<u32>> Add for ModU32<Mod> {
    type Output = Self;

    fn add(mut self, rhs: Self) -> Self {
      self += rhs;
      self
    }
  }

  impl<Mod: Constant<u32>> AddAssign for ModU32<Mod> {
    fn add_assign(&mut self, rhs: Self) {
      self.repr += rhs.repr;
      if self.repr >= Mod::get() {
        self.repr -= Mod::get();
      }
