fn read_stdin() -> String {
    use std::io::Read;
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    input
}

fn scan<'a, I: Iterator<Item = &'a str>, T: std::str::FromStr>(tokens: &mut I) -> T {
    tokens.next().unwrap().parse().ok().unwrap()
}

fn vec<T, F: FnMut(usize) -> T>(n: usize, mut f: F) -> Vec<T> {
    (0..n).map(|i| f(i)).collect()
}

const MODULO: usize = 998244353;

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let s: usize = scan(tokens);
    let a: Vec<usize> = vec(n, |_| scan(tokens));
    let mut count: Vec<usize> = vec![0; s];
    let mut ans: usize = 0;
    for i in 0..n {
        if a[i] > s {
            continue;
        }
        ans = (ans + count[s - a[i]] * (n - i)) % MODULO;
        for x in (a[i] + 1..s).rev() {
            count[x] = (count[x] + count[x - a[i]]) % MODULO;
        }
        if a[i] == s {
            ans = (ans + (i + 1) * (n - i)) % MODULO;
        } else {
            count[a[i]] = (count[a[i]] + i + 1) % MODULO;
        }
    }
    println!("{}", ans);
}

