const M: usize = 998244353;

fn main() {
    input! {
        n: usize,
        s: usize,
        a: [usize; n],
    }

    let mut count = vec![0; 3001];
    let mut ans = 0;
    for i in 0..n {
        if a[i] < s {
            let x = count[s - a[i]];
            ans += (n - i) * x;
        } else if a[i] == s {
            ans += (n - i) * (i + 1);
        }

        ans %= M;

        let mut next_count = vec![0; 3001];
        for j in (0..3001).rev() {
            if j + a[i] > 3000 {
                continue;
            }
            next_count[j + a[i]] = count[j];
        }
        for j in 0..3001 {
            next_count[j] += count[j];
            next_count[j] %= M;
        }
        next_count[a[i]] += i + 1;
        next_count[a[i]] %= M;
        count = next_count;
    }
    println!("{}", ans);
}

fn main() {
    let v = read_vec::<usize>();
    let (n, s) = (v[0], v[1]);
    let a = read_vec::<usize>();
    let mut q = vec![Modulo(0i64); s + 1];
    let mut ans = Modulo(0);
    for i in 0..n {
        q[0] += 1;
        let mut q2 = vec![Modulo(0i64); s + 1];
        for j in 0..s + 1 {
            q2[j] += q[j];
            if j + a[i] <= s {
                q2[j + a[i]] += q[j];
            }
        }
        q = q2;
        ans += q[s];
    }
    println!("{}", ans);
}

