fn dp(memo: &mut Vec<Vec<Vec<i32>>>, vs: &Vec<i32>, i: usize, j: usize, s: i32) -> i32{
  let m = memo[i][j][s as usize];
  if m >= 0 {
    m
  } else if i == j {
    if s == vs[j] || s == 0 {
      1
    } else {
      0
    }
  } else {
    let v = vs[j];
    let result = if s < v {
      dp(memo, vs, i, j - 1, s)
    } else {
      dp(memo, vs, i, j - 1, s - v) + dp(memo, vs, i, j - 1, s)
    };
    memo[i][j][s as usize] = result;
    result
  }
}

