const MOD: u64 = 998244353;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let (n, s) = scanner.read_two::<usize>().unwrap();
    let arr = scanner.read_vector::<usize>().unwrap();
    let ans = solve(n, s, &arr);
    println!("{}", ans);
}

fn solve(n: usize, s: usize, arr: &[usize]) -> u64 {
    let mut dp = vec![0u64; s + 1];
    for i in 0..n {
        if arr[i] > s {
            continue;
        }
        let mut new_dp = dp.clone();
        dp[0] = (i + 1) as u64;
        for j in arr[i]..s {
            new_dp[j] += dp[j - arr[i]];
            new_dp[j] %= MOD;
        }
        new_dp[s] += (dp[s - arr[i]] * (n - i) as u64) % MOD;
        new_dp[s] %= MOD;
        dp = new_dp;
    }
    dp[s]
}

