fn solve() {
    let (n,s) = get!(usize, usize);
    let a = get!([usize]);

    let mut dp = vec![vec![ModInt::new(0); s+1];n+1];
    dp[0][0] = ModInt::new(1);
    let mut sum = ModInt::new(0);
    for i in 0..n {
        for e in 0..s+1 {
            let tmp = if a[i] > e {
                dp[i][e]
            } else {
                dp[i][e] + dp[i][e-a[i]]
            };
            dp[i+1][e] += tmp;
        }
        dp[i+1][0] += 1;
        sum += dp[i+1][s];
    }

    println!("{}", sum);
}

