        for j in 0..s {
            dp[i][j] = dp[i][j] + dp[i - 1][j];
        }

        // まだ選んでなくて、Aiを足す場合
        if val == s {
            ans += (i * (n - i + 1)) as i64
        } else {
            dp[i][val] += i as i64;
        }
    }
