fn solve() {
    let (n,s) = read!(usize,usize);
    let a = read!([usize]);
    let mut dp = vec![[ModInt(0);3001];n+1];
    dp[0][0] = ModInt(1);
    let mut ans = ModInt(0);
    for i in 0..n {
        for j in 0..3001 {
            dp[i+1][j] = dp[i+1][j] + dp[i][j];
            let val = j + a[i];
            if val <= 3000 {
                if j==0 {
                    dp[i+1][val] = ModInt(i+1);
                }
                else{
                    dp[i+1][val] = dp[i+1][val] + dp[i][j];
                }
                if val==s {
                    ans += dp[i+1][val]*ModInt(n-i);
                }
            }
        }
    }
    println!("{}",ans.0);
}

fn run() {
    solve();
}

