use std::io::Read;

fn trans(dp: &mut [ModInt], a: usize) {
    for i in (a..dp.len()).rev() {
        dp[i] = dp[i] + dp[i - a];
    }
}

fn calc(a: &[usize], w: usize) -> ModInt {
    if a.len() == 1 {
        return if a[0] == w {ModInt::one()} else {ModInt::zero()};
    }
    let m = a.len() / 2;
    let mut ans = calc(&a[..m], w) + calc(&a[m..], w);
    let (l, r) = a.split_at(m);
    let mut dp = vec![ModInt::zero(); w + 1];
    dp[0] = ModInt::one();
    let mut total = vec![ModInt::zero(); w + 1];
    for a in l.iter().rev() {
        trans(&mut dp, *a);
        for (total, dp) in total.iter_mut().zip(dp.iter()) {
            *total += *dp;
        }
    }
    let left = total;
    let mut dp = vec![ModInt::zero(); w + 1];
    dp[0] = ModInt::one();
    let mut total = vec![ModInt::zero(); w + 1];
    for a in r.iter() {
        trans(&mut dp, *a);
        for (total, dp) in total.iter_mut().zip(dp.iter()) {
            *total += *dp;
        }
    }
    for (l, r) in left.iter().zip(total.iter().rev()) {
        ans += *l * *r;
    }
    ans
}

