macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, s): (usize, usize) = parse!(it, 2);
    let a: Vec<usize> = parse!(it, n);
    let mut dp: Vec<Vec<Vec<musize>>> = vec![vec![vec![0.into(); 3]; s + 1]; n + 1];
    dp[0][0][0] = 1.into();
    for i in 0..n {
        for j in 0..(s + 1) {
            dp[i + 1][j][0] = dp[i][j][0];
            dp[i + 1][j][1] += dp[i][j][1] + dp[i][j][0];
            dp[i + 1][j][2] += dp[i][j][2] + dp[i][j][1] + dp[i][j][0];
            if j + a[i] <= s {
                dp[i + 1][j + a[i]][1] += dp[i][j][1] + dp[i][j][0];
                dp[i + 1][j + a[i]][2] += dp[i][j][1] + dp[i][j][0];
            }
        }
    }
    println!("{}", dp[n][s][2]);
}

