const P: usize = 998244353;

fn main() {
    let (N, S) = read!(usize, usize);
    let A = read![[usize]];

    // (L, x, R) (ただし L≤x(0) < ... < x(k) < R) の個数。
    let mut total = 0_usize;

    // dp[i][s] = (状態の数)
    // 状態:
    //     L と x(i) (L 以上 i 未満) の一部を決定済み
    //     A(x(i)) の総和が s に等しい
    let mut dp = vec![vec![0; S + 1]; N + 1];

    for i in 0..N {
        // (L=i, x=(), R=?) がある。
        dp[i][0] = 1;
    }

    for i in 0..N {
        let a = A[i];

        for s in 0..S + 1 {
            // 列 x に i を加えない遷移
            dp[i + 1][s] += dp[i][s];

            // 列 x に i を加える遷移。総和が S を超えるケースは数える意味がないので無視。
            if s + a <= S {
                dp[i + 1][s + a] += dp[i][s];
            }
        }

        for s in 0..S + 1 {
            dp[i + 1][s] %= P;
        }

        // R=i+1 に決定する遷移。総和が S でないケースは数える意味がないので無視。
        total += dp[i + 1][S];
        total %= P;
    }

    println!("{}", total);
}

