	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let t: usize = s.next().unwrap().parse().unwrap();
	let a: Vec<usize> = s.take(n).map(|a| a.parse().unwrap()).collect();
	let mut dp = vec![0; t + 1];
	let mut ans = 0;
	for a in a {
		dp[0] = (dp[0] + 1) % MOD;
		for i in (a..=t).rev() {
			dp[i] = (dp[i] + dp[i - a]) % MOD;
		}
		ans = (ans + dp[t]) % MOD;
	}
	println!("{}", ans);
}

