fn solve(aa: &[u16], s: u16, closed: bool, memo: &mut [Vec<Vec<Option<ModP>>>]) -> ModP {
    memo[aa.len()][s as usize][closed as usize].unwrap_or_else(|| {
        let ans = if s == 0 {
            modp((aa.len()+1) as u64)
        } else {
            aa.split_first().map_or(modp(0), |(&hd, tl)| {
                let mut ans = modp(0);
                if let Some(rest) = s.checked_sub(hd) {
                    ans += solve(tl, rest, true, memo);
                }
                if closed {
                    ans += solve(tl, s, true, memo);
                } else {
                    ans += solve(tl, s, true, memo) + solve(tl, s, false, memo);
                }
                ans
            })
        };
        memo[aa.len()][s as usize][closed as usize] = Some(ans);
        ans
    })
}

