            impl From<$t> for ModInt {
                fn from(v: $t) -> Self {
                    ModInt::from(v as i64)
                }
            }
        )*
    };
}

macro_rules! ops_impl {
    ($($t:ty)*) => {
        $(
            impl AddAssign<$t> for ModInt {
                fn add_assign(&mut self, rhs: $t) {
                    *self += ModInt::from(rhs);
                }
            }

            impl Add<$t> for ModInt {
                type Output = Self;
                fn add(mut self, rhs: $t) -> Self {
                    self += rhs;
                    self
                }
            }
            impl SubAssign<$t> for ModInt {
                fn sub_assign(&mut self, rhs: $t) {
                    self.0 = round_mod(self.0 + MOD - ModInt::from(rhs).0);
                }
            }
            impl Sub<$t> for ModInt {
                type Output = Self;
                fn sub(mut self, rhs: $t) -> Self {
                    self -= rhs;
                    self
                }
            }

            impl MulAssign<$t> for ModInt {
                fn mul_assign(&mut self, rhs: $t) {
                    self.0 = self.0 * ModInt::from(rhs).0 % MOD;
                }
            }

            impl Mul<$t> for ModInt {
                type Output = Self;
                fn mul(mut self, rhs: $t) -> Self {
                    self *= rhs;
                    self
                }
            }

            impl DivAssign<$t> for ModInt {
                fn div_assign(&mut self, rhs: $t) {
                    self.0 = self.0 * ModInt::from(rhs).pow(MOD as i64 - 2).0 % MOD;
                }
            }

            impl Div<$t> for ModInt {
                type Output = Self;
                fn div(mut self, rhs: $t) -> Self {
                    self /= rhs;
                    self
                }
            }

        )*
    };
}

