macro_rules! inc {
    ($x:expr, $dx:expr) => {{
        let a = $dx;
        $x = $x + a;
    }}
}

macro_rules! min {
    (.. $x:expr) => {{
        let mut it = $x.iter();
        it.next().map(|z| it.fold(z, |x, y| min!(x, y)))
    }};
    ($x:expr) => ($x);
    ($x:expr, $($ys:expr),*) => {{
        let t = min!($($ys),*);
        if $x < t { $x } else { t }
    }}
}
macro_rules! max {
    (.. $x:expr) => {{
        let mut it = $x.iter();
        it.next().map(|z| it.fold(z, |x, y| max!(x, y)))
    }};
    ($x:expr) => ($x);
    ($x:expr, $($ys:expr),*) => {{
        let t = max!($($ys),*);
        if $x > t { $x } else { t }
    }}
}
macro_rules! ewriteln {
    ($($args:expr),*) => { let _ = writeln!(&mut std::io::stderr(), $($args),*); };
}
macro_rules! trace {
    ($x:expr) => { ewriteln!(">>> {} = {:?}", stringify!($x), $x) };
    ($($xs:expr),*) => { trace!(($($xs),*)) }
}
macro_rules! put {
    (.. $x:expr) => {{
        let mut it = $x.iter();
        if let Some(x) = it.next() { print!("{}", x); }
        for x in it { print!(" {}", x); }
        println!("");
    }};
    ($x:expr) => { println!("{}", $x) };
    ($x:expr, $($xs:expr),*) => { print!("{} ", $x); put!($($xs),*) }
}

const M: i64 = 998244353;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let s: usize = sc.cin();
    let xs: Vec<usize> = sc.vec(n);

    let mut dp = vec![vec![ModInt::new(0, M); 4000]; 4000];
    let mut ans = ModInt::new(0, M);

    for i in 0..n {
        if i == 0 {
            dp[0][xs[0]] += 1;
            // if xs[0] == s {
            //     ans += n as i64;
            // }
        } else {
            dp[i][xs[i]] += (i + 1) as i64;
            for k in 0..s+1 {
                inc!(dp[i][k], dp[i-1][k]);
                if k >= xs[i] {
                    inc!(dp[i][k], dp[i-1][k - xs[i]]);
                    // if k == s {
                    //     ans += dp[i-1][k - xs[i]] * ((n - i) as i64);
                    // }
                }
            }
        }
        // trace!(&dp[i][0..11].iter().map(|x| x.res).collect::<Vec<_>>());
        ans += dp[i][s];
    }
    put!(ans);
}

use std::io::{self, Write};
use std::str::FromStr;
use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Self { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> { self.cin::<String>().chars().collect() }
    fn vec<T: FromStr>(&mut self, n: usize) -> Vec<T> { (0..n).map(|_| self.cin()).collect() }
}

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
struct ModInt { res: i64, md: i64 }

impl ModInt {
    fn new(res: i64, md: i64) -> Self {
        ModInt { res: res, md: md }
    }
    fn inv(self) -> Self {
        fn exgcd(r0: i64, a0: i64, b0: i64, r: i64, a: i64, b: i64)
                -> (i64, i64, i64) {
            if r > 0 {
                exgcd(r, a, b, r0 % r, a0 - r0 / r * a, b0 - r0 / r * b)
            } else {
                (a0, b0, r0)
            }
        }
        let (a, _, r) = exgcd(self.res, 1, 0, self.md, 0, 1);
        if r != 1 { panic!("{:?} has no inverse!", self); }
        ModInt::new(((a % self.md) + self.md) % self.md, self.md)
    }
    fn pow(self, n: i64) -> Self {
        if n < 0 {
            self.pow(-n).inv()
        } else if n == 0 {
            ModInt::new(1, self.md)
        } else if n == 1 {
            self
        } else {
            let mut x = (self * self).pow(n / 2);
            if n % 2 == 1 { x *= self }
            x
        }
    }
}
impl std::fmt::Display for ModInt {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.res)
    }
}
impl std::ops::Neg for ModInt {
    type Output = Self;
    fn neg(self) -> Self {
        if self.res == 0 { return self }
        ModInt { res: self.md - self.res, md: self.md }
