type BoxResult<T> = Result<T, Box<std::error::Error>>;

const MOD: u64 = 998244353;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let (n, s) = scanner.read_two::<usize>().unwrap();
    let arr = scanner.read_vector::<usize>().unwrap();
    let mut dp = vec![vec![]; s + 1];
    for i in 0..n {
        for j in arr[i]..(s + 1) {
            if j == arr[i] {
                dp[j].push((i, i));
            } else {
                let pairs = dp[j - arr[i]].clone();
                for (l, r) in pairs.into_iter() {
                    if r == i {
                        continue;
                    }
                    dp[j].push((l, i));
                }
            }
        }
    }
    let mut ans = 0;
    for &(l, r) in dp[s].iter() {
        ans += (l + 1) as u64 * (n - r) as u64;
        ans %= MOD;
    }
    println!("{}", ans);
}

