define_mod!(P, MOD);
type ModInt = mod_int::ModInt<P>;

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }
    input! {
        n: usize, s: usize,
        a: [usize; n],
    }
    let mut dp = vec![vec![ModInt::new(0); s + 1]; n + 1];
    for i in 0..n {
        // initiate
        if a[i] <= s {
            dp[i + 1][a[i]] += i as i64 + 1;
        }
        // progress
        for j in 0..s + 1 {
            let val = dp[i][j];
            if j + a[i] <= s {
                dp[i + 1][j + a[i]] += val;
            }
            dp[i + 1][j] += val;
        }

    }
    let mut tot = ModInt::new(0);
    for i in 1..n + 1 {
        tot += (dp[i][s] - dp[i - 1][s]) * (n + 1 - i) as i64;
    }
    puts!("{}\n", tot);
}

